const items = $input.all().map(i => i.json);
const run = $('Initialize Run Metadata').first().json;
const timezone = run.timezone || 'America/Los_Angeles';
function zonedParts(date, timeZone) { const parts = new Intl.DateTimeFormat('en-US', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).formatToParts(date); const out = {}; for (const p of parts) if (p.type !== 'literal') out[p.type] = Number(p.value); if (out.hour === 24) out.hour = 0; return out; }
function zonedTimeToUtcMs(y, m, d, h, min, s, timeZone) { let utc = Date.UTC(y, m - 1, d, h, min, s || 0); for (let i = 0; i < 4; i++) { const p = zonedParts(new Date(utc), timeZone); const asIfUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second || 0); const target = Date.UTC(y, m - 1, d, h, min, s || 0); utc -= (asIfUtc - target); } return utc; }
function addDaysYmd(y, m, d, delta) { const dt = new Date(Date.UTC(y, m - 1, d + delta, 12)); return { year: dt.getUTCFullYear(), month: dt.getUTCMonth() + 1, day: dt.getUTCDate() }; }
function expectedCycle(now) { const p = zonedParts(now, timezone); let y = p.year, m = p.month, d = p.day, h = 13; if (p.hour < 3) { const prev = addDaysYmd(y, m, d, -1); y = prev.year; m = prev.month; d = prev.day; h = 13; } else if (p.hour < 13) h = 3; else h = 13; const startUtcMs = zonedTimeToUtcMs(y, m, d, h, 0, 0, timezone); const pad = n => String(n).padStart(2, '0'); return { cycle_label: pad(h) + ':00', timezone, expected_start_local: y + '-' + pad(m) + '-' + pad(d) + 'T' + pad(h) + ':00:00', expected_start_utc: new Date(startUtcMs).toISOString(), start_utc_ms: startUtcMs }; }
function displaySeverity(dataStatus, currentState) { if (currentState === 'MISSED_RUN' || currentState === 'STALE_FROM_OLDER_CYCLE') return 'watch'; if (dataStatus === 'blocked' || dataStatus === 'failed_validation') return 'alert'; if (['degraded', 'stale', 'failed_fetch', 'using_last_known_good'].includes(dataStatus)) return 'watch'; if (dataStatus === 'ok' || dataStatus === 'no_relevant_events') return 'normal'; return 'unknown'; }
function getTime(d) { const t = Date.parse(d?.generated_at || d?.published_at || d?.last_fetch_at || ''); return Number.isFinite(t) ? t : null; }
const cycle = expectedCycle(new Date(run.generated_at));
const severityRank = { normal: 0, unknown: 1, watch: 2, alert: 3 };
const lanes = {}; const completeness = []; const missedRuns = []; let worst = 'normal'; let hasFailed = false;
for (const expected of run.lanes) { const item = items.find(i => i.lane_id === expected.lane_id) || { lane_id: expected.lane_id, lane_label: expected.label, available: false, data: null, parse_error: 'lane output not present in merge input' }; const d = item.data; const observedMs = getTime(d); const ranCurrentCycle = item.available && observedMs !== null && observedMs >= cycle.start_utc_ms; const currentCycleState = !item.available ? 'MISSED_RUN' : (ranCurrentCycle ? 'RAN_CURRENT_CYCLE' : 'STALE_FROM_OLDER_CYCLE'); const dataStatus = d?.data_status || (d?.status === 'ok' ? 'ok' : d?.status || null); const lkgUsed = !!(d?.connector_health?.used_last_known_good || d?.uses_last_known_good || dataStatus === 'using_last_known_good'); const eventCount = Array.isArray(d?.events) ? d.events.length : (Array.isArray(d?.deduplicated_events) ? d.deduplicated_events.length : 0); const sev = displaySeverity(dataStatus, currentCycleState); const laneRecord = { lane_label: item.lane_label || expected.label, available: !!item.available, current_cycle_state: currentCycleState, ran_current_cycle: ranCurrentCycle, expected_cycle: cycle.cycle_label, expected_start_utc: cycle.expected_start_utc, latest_run_id: d?.run_id || null, latest_execution_or_report_at: observedMs === null ? null : new Date(observedMs).toISOString(), display_severity: sev, data_status: dataStatus, freshness: d?.freshness || null, published_at: d?.published_at || null, generated_at: d?.generated_at || null, connector_health: d?.connector_health || null, lkg_used: lkgUsed, event_count: eventCount, source_health_summary: Array.isArray(d?.source_health) ? d.source_health.map(s => ({ source_id: s.source_id, status: s.status, error_count: Array.isArray(s.errors) ? s.errors.length : 0, warning_count: Array.isArray(s.warnings) ? s.warnings.length : 0 })) : [], pointer_or_parse_error: item.parse_error || null, events: d?.events || d?.deduplicated_events || [] }; lanes[expected.lane_id] = laneRecord; completeness.push({ lane_id: expected.lane_id, latest_run_id: laneRecord.latest_run_id, current_cycle_state: currentCycleState, ran_current_cycle: ranCurrentCycle, latest_execution_or_report_at: laneRecord.latest_execution_or_report_at, data_status: dataStatus, lkg_used: lkgUsed, event_count: eventCount }); if (currentCycleState !== 'RAN_CURRENT_CYCLE') missedRuns.push({ lane_id: expected.lane_id, lane_label: expected.label, current_cycle_state: currentCycleState, latest_run_id: laneRecord.latest_run_id, latest_execution_or_report_at: laneRecord.latest_execution_or_report_at }); if (['failed_validation', 'failed_fetch', 'blocked'].includes(dataStatus)) hasFailed = true; if (severityRank[sev] > severityRank[worst]) worst = sev; }
const systemResult = hasFailed ? 'FAILED' : (missedRuns.length || worst === 'watch' || worst === 'unknown' ? 'DEGRADED' : 'PASSED');
const overallMessage = systemResult === 'FAILED' ? 'One or more source lanes failed validation, fetch, or are blocked.' : missedRuns.length ? 'One or more expected source lanes did not produce current-cycle evidence.' : worst === 'watch' ? 'All expected source lanes ran, with one or more degraded, stale, or using last-known-good data.' : 'All expected source lanes ran for the current cycle.';
return [{ json: { schema_version: '1.0.0', connector_id: '20_STATUS_PUBLISHER', connector_version: 'v0004', workflow_name: 'v04.UWI_LANE20', generated_at: run.generated_at, run_id: run.run_id, current_cycle: { expected_cycle: cycle.cycle_label, timezone, expected_start_local: cycle.expected_start_local, expected_start_utc: cycle.expected_start_utc, lane20_generated_at: run.generated_at }, system_result: systemResult, overall: { display_severity: worst, message: overallMessage }, missed_runs: missedRuns, lane_cycle_completeness: completeness, lanes, release_input: { path: run.output_root + '/public/workflow20-status-latest.json', policy: 'current Lane 20 assembled snapshot for GitHub public-package build input' }, severity_mapping_note: 'display_severity is a workflow-20-only display tier; each lane native data_status and events are preserved above.' } }];

