  sources: [
    { sourceId: 'atmo-france', sourceName: 'Atmo France / Atmo Data', endpoint: config.atmoBaseUrl + config.atmoIndicesPath, category: 'air_quality' },
    { sourceId: 'atmo-france-episodes', sourceName: 'Atmo France / Atmo Data (pollution episodes)', endpoint: config.atmoBaseUrl + config.atmoEpisodesPath, category: 'pollution_episode' },
  ],
  atmoIndex,
  pollutionEpisodes,
  pollutionEpisodeSummary: { activeEpisodeCount: episodeSummary.activeEpisodeCount, zeroActiveEpisodes: episodeSummary.zeroActiveEpisodes },
  zones,
  records: [...atmoIndex, ...pollutionEpisodes],
  sourceHealth,
  attribution: { required: true, license: 'ODbL', source: 'Atmo France / Atmo Data' },
  validation: { passed: validation.passed, errors: validation.errors || [], warnings: validation.warnings || [] },
  compatibility: {
    targetMonitoringFeed: 'public/cdm-monitoring-status.json',
    targetMapFeed: 'public/data/atmo-air-quality-map.json',
    mode: 'compatibility_candidate',
  },
};

function emit(path, payload, label) {
  return { json: { targetPath: path, label, jsonText: JSON.stringify(payload, null, 2) + '\n' } };
}

const atmoIndexFeed = { generatedAt: config.generatedAt, source: 'atmo-france', observations: atmoIndex };
const episodesFeed = { generatedAt: config.generatedAt, source: 'atmo-france-episodes', activeEpisodeCount: episodeSummary.activeEpisodeCount, observations: pollutionEpisodes };
const zonesFeed = { generatedAt: config.generatedAt, corridorKm: Number(config.corridorKm), corridorZoneCount: zones.length, zones };
const healthFeed = { generatedAt: config.generatedAt, sources: sourceHealth };
const compatMonitoringFeed = { generatedAt: config.generatedAt, sourceStatus: sourceHealth, alerts: [...atmoIndex, ...pollutionEpisodes] };
const compatMapFeed = {
  schemaVersion: 1,
  generatedAt: config.generatedAt,
  maxAgeHours: Math.round(Number(config.staleAfterMinutes) / 60),
  source: 'Atmo France and regional AASQA',
  license: 'ODbL',
  attribution: config.attributionText,
  palette: { '1': '#50f0e6', '2': '#50ccaa', '3': '#f0e641', '4': '#ff5050', '5': '#960032', '6': '#7d2181' },
  markers: zones,
};

return [
  emit(config.outputDirectory + '/air-quality-connector-output.json', combined, 'air-quality-connector-output'),
  emit(config.outputDirectory + '/air-quality-atmo-index.normalized.json', atmoIndexFeed, 'air-quality-atmo-index.normalized'),
  emit(config.outputDirectory + '/air-quality-pollution-episodes.normalized.json', episodesFeed, 'air-quality-pollution-episodes.normalized'),
  emit(config.outputDirectory + '/air-quality-zones.normalized.json', zonesFeed, 'air-quality-zones.normalized'),
  emit(config.outputDirectory + '/air-quality-source-health.json', healthFeed, 'air-quality-source-health'),
  emit(config.outputDirectory + '/air-quality-monitoring-status.compat.json', compatMonitoringFeed, 'air-quality-monitoring-status.compat'),
  emit(config.outputDirectory + '/atmo-air-quality-map.compat.json', compatMapFeed, 'atmo-air-quality-map.compat'),
];

const output = [];
for (const item of $input.all()) {
  const buf = Buffer.from(item.json.jsonText, 'utf8');
  const fileName = String(item.json.targetPath).split('/').pop();
  const binary = await this.helpers.prepareBinaryData(buf, fileName, 'application/json');
  output.push({ json: item.json, binary: { data: binary } });
}
return output;

const LABELS = new Set(['air-quality-connector-output', 'air-quality-atmo-index.normalized', 'air-quality-pollution-episodes.normalized', 'air-quality-zones.normalized', 'air-quality-source-health', 'air-quality-monitoring-status.compat', 'atmo-air-quality-map.compat']);
const results = [];
for (const item of $input.all()) {
  const targetPath = (item.json && item.json.targetPath) || 'unknown';
  const fileName = String(targetPath).split('/').pop() || 'unknown';
  const label = fileName.replace(/\.json$/, '');
  if (!item.binary || !item.binary.data) {
    results.push({ json: { label, targetPath, validJson: false, bytes: 0, error: 'No binary data read back for ' + fileName } });
    continue;
  }
  const text = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (err) {
    results.push({ json: { label, targetPath, validJson: false, bytes: Buffer.byteLength(text, 'utf8'), error: 'Invalid JSON: ' + err.message } });
    continue;
  }
  let shapeError = null;
  if (label === 'air-quality-connector-output' && (!parsed.connectorId || !Array.isArray(parsed.sourceHealth) || !parsed.validation)) {
    shapeError = 'air-quality-connector-output missing connectorId, sourceHealth[], or validation';
  }
  if (label === 'air-quality-source-health' && !Array.isArray(parsed.sources)) {
    shapeError = 'air-quality-source-health missing sources[]';
  }
  if (!LABELS.has(label)) shapeError = shapeError || ('Unexpected output label: ' + label);
  results.push({ json: { label, targetPath, validJson: !shapeError, bytes: Buffer.byteLength(text, 'utf8'), error: shapeError } });
}
return results;

const config = $items('Set Connector Config')[0].json;
const validationResults = $input.all().map((i) => i.json || {});
const generatedAt = config.generatedAt || new Date().toISOString();
const completedAt = new Date().toISOString();
const failures = validationResults.filter((r) => r.validJson !== true || r.error);
const errors = failures.map((f) => ({ label: f.label, targetPath: f.targetPath, message: f.error || 'Output file did not pass validation' }));

return [{
  json: {
    recordKind: 'runDiagnostics',
    ok: errors.length === 0,
    connectorId: config.connectorId,
    workflowVersion: config.workflowVersion,
    generatedAt,
    completedAt,
    validationStatus: errors.length === 0 ? 'passed' : 'failed',
    writeStatus: validationResults.length > 0 ? 'attempted' : 'not_attempted',
    infraBlocked: false,
    outputFilenames: validationResults.map((r) => r.targetPath).filter(Boolean),
    errors,
    warnings: [],
    note: 'If Atmo Login / Fetch Token fails with 401/403, classify as CREDENTIALS_BLOCKED. If Write Air Quality Output Files or Read Back Air Quality Output Files fail upstream with a file-access error rather than reaching this node, classify the run as INFRA_BLOCKED_AT_OUTPUT_WRITE, not FAILED.',
  },
}];

// n8n Code node: "Fetch Dashboard Data"
// Port of BTF_local_CDM_STATUS_PAGE_PROJECT_ALT_BOD_NANTES/scripts/fetch_bod_nantes_dashboard_data.py into n8n.
// Input: one item from "Atmo Login" with json.token (bearer token).
// Output: one item, json = the full latest.json-shaped object.

const ctx = this;
const token = $input.first().json.token;

const TOWNS = [
  { ride_day: "RD00", town: "Bordeaux",               lat: 44.838092, lon: -0.577445 },
  { ride_day: "RD01", town: "Carcans / Maubuisson",     lat: 45.078945, lon: -1.045432 },
  { ride_day: "RD02", town: "Soulac-sur-Mer",            lat: 45.515114, lon: -1.123138 },
  { ride_day: "RD03", town: "Rochefort",                 lat: 45.936769, lon: -0.962724 },
  { ride_day: "RD04", town: "Marans",                    lat: 46.309609, lon: -0.993248 },
  { ride_day: "RD05", town: "Jard-sur-Mer",              lat: 46.416286, lon: -1.582025 },
  { ride_day: "RD06", town: "Saint-Hilaire-de-Riez",     lat: 46.713418, lon: -1.955273 },
  { ride_day: "RD07", town: "Bouin",                     lat: 46.974497, lon: -1.999023 },
  { ride_day: "RD08", town: "Saint-Brevin-les-Pins",     lat: 47.254919, lon: -2.163416 },
  { ride_day: "RD09", town: "Nantes",                    lat: 47.217835, lon: -1.55502 },
];

const ZONE_CODES = {
  "Bordeaux":                { insee: "33063", epci: "243300316" },
  "Carcans / Maubuisson":     { insee: "33097", epci: "200070720" },
  "Soulac-sur-Mer":            { insee: "33514", epci: "200070720" },
  "Rochefort":                 { insee: "17299", epci: "200041762" },
  "Marans":                    { insee: "17218", epci: "200041499" },
  "Jard-sur-Mer":              { insee: "85114", epci: "200071900" },
  "Saint-Hilaire-de-Riez":     { insee: "85226", epci: "200023778" },
  "Bouin":                     { insee: "85029", epci: "200071629" },
  "Saint-Brevin-les-Pins":     { insee: "44154", epci: "244400586" },
  "Nantes":                    { insee: "44109", epci: "244400404" },
};

const HISTORICAL_DATES = ["2025-09-01", "2025-09-15", "2024-09-01", "2024-09-15"];

const ATMO_BASE = "https://admindata.atmo-france.org";
const ATMO_DATA_PATH = "/api/data/112";
const ATMO_WFS_BASE = "https://data.atmo-france.org/geoserver/ind/ows";

// The 6 official French Indice ATMO severity levels are shown as their own
// distinct states -- not collapsed into a smaller custom scale -- per official
// ATMO taxonomy. code_qual 7 "Evenement" is a separate Alert flag, not a
// severity level, and is never folded into any of the 6.
const QUAL_LABEL = { 1: "Bon", 2: "Moyen", 3: "Dégradé", 4: "Mauvais", 5: "Très mauvais", 6: "Extrêmement mauvais", 7: "Événement" };
const QUAL_LABEL_EN = { 1: "Good", 2: "Moderate", 3: "Degraded", 4: "Poor", 5: "Very Poor", 6: "Extremely Poor", 7: "Alert" };
const TIER_COLOR = {
  Good: "#16a34a", Moderate: "#84cc16", Degraded: "#ca8a04", Poor: "#ea580c",
  "Very Poor": "#dc2626", "Extremely Poor": "#7f1d1d", Alert: "#7c3aed",
};
const TIER_SEVERITY = { Good: 1, Moderate: 2, Degraded: 3, Poor: 4, "Very Poor": 5, "Extremely Poor": 6, Alert: 7 };

function tierForCode(codeQual) {
  if (codeQual === null || codeQual === undefined) return null;
  return QUAL_LABEL_EN[codeQual] || null;
}

// n8n's Code node sandbox (JS Task Runner) does not provide URLSearchParams.
function qs(obj) {
  return Object.entries(obj)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join("&");
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// Running unattended on a 12h schedule -- retry transient upstream failures (5xx, network
// errors) a few times before giving up. Do NOT retry 4xx (e.g. 404 "no data for this
// zone/date"), those are meaningful responses the callers already handle.
async function fetchJson(url, headers, attempt) {
  attempt = attempt || 1;
  try {
    return await ctx.helpers.httpRequest({
      method: "GET",
      url,
      headers: headers || {},
      json: true,
      timeout: 30000,
    });
  } catch (e) {
    const status =
      (e && e.response && (e.response.status || e.response.statusCode)) ||
      e.statusCode || e.httpCode || e.status || undefined;
    const isTransient = status === undefined || status >= 500;
    if (isTransient && attempt < 3) {
      await sleep(1000 * attempt);
      return fetchJson(url, headers, attempt + 1);
    }
    const err = new Error(e && e.message ? e.message : String(e));
    if (status !== undefined) err.status = Number(status);
    throw err;
  }
}

async function atmoQuery(zoneCode, dateEch) {
  const filt = { code_zone: { operator: "=", value: zoneCode }, date_ech: { operator: "=", value: dateEch } };
  const url = `${ATMO_BASE}${ATMO_DATA_PATH}/${encodeURIComponent(JSON.stringify(filt))}?withGeom=false`;
  try {
    const data = await fetchJson(url, { Authorization: `Bearer ${token}` });
    const feats = data.features || [];
    if (!feats.length) return null;
    return feats[0].properties;
  } catch (e) {
    if (e.status !== undefined) return null;
    throw e;
  }
}

async function currentAirQuality(town) {
  const zones = ZONE_CODES[town];
  const today = new Date().toISOString().slice(0, 10);
  for (const [zoneType, zoneCode] of [["commune", zones.insee], ["EPCI", zones.epci]]) {
    const props = await atmoQuery(zoneCode, today);
    if (props && props.code_qual !== null && props.code_qual !== undefined) {
      return {
        code_qual: props.code_qual,
        tier: tierForCode(props.code_qual),
        label_fr: QUAL_LABEL[props.code_qual] || null,
        zone_type: zoneType,
        zone_code: zoneCode,
        as_of: props.date_maj || null,
      };
    }
  }
  return { code_qual: null, tier: null, label_fr: null, zone_type: null, zone_code: null, as_of: null };
}

function isoWeekPartition(dateStr) {
  let d = new Date(dateStr + "T00:00:00Z");
  const day = (d.getUTCDay() + 6) % 7;
  d.setUTCDate(d.getUTCDate() - day + 3);
  const year = d.getUTCFullYear();
  let firstThu = new Date(Date.UTC(year, 0, 4));
  const fDay = (firstThu.getUTCDay() + 6) % 7;
  firstThu.setUTCDate(firstThu.getUTCDate() - fDay);
  const week = 1 + Math.round((d - firstThu) / (7 * 86400000));
  return `${year}w${String(week).padStart(2, "0")}`;
}

async function historicalAirQuality(zoneCode, targetDate) {
  const partition = isoWeekPartition(targetDate);
  const filterXml =
    `<Filter><And>` +
    `<PropertyIsEqualTo><PropertyName>date_ech</PropertyName><Literal>${targetDate}</Literal></PropertyIsEqualTo>` +
    `<PropertyIsEqualTo><PropertyName>code_zone</PropertyName><Literal>${zoneCode}</Literal></PropertyIsEqualTo>` +
    `</And></Filter>`;
  const params = qs({
    SERVICE: "WFS", VERSION: "2.0.0", REQUEST: "GetFeature",
    TYPENAMES: "ind:ind_atmo_partition_week", OUTPUTFORMAT: "application/json",
    FILTER: filterXml, viewparams: `PARTITION_WEEK_ID:${partition}`,
  });
  const url = `${ATMO_WFS_BASE}?${params}`;
  try {
    const data = await fetchJson(url);
    const feats = data.features || [];
    if (!feats.length) return null;
    return feats[0].properties;
  } catch (e) {
    if (e.status !== undefined) return null;
    throw e;
  }
}

async function historicalAqForTown(town, targetDate) {
  const zones = ZONE_CODES[town];
  for (const zoneCode of [zones.insee, zones.epci]) {
    const props = await historicalAirQuality(zoneCode, targetDate);
    if (props && props.code_qual !== null && props.code_qual !== undefined) return props.code_qual;
  }
  return null;
}

// Official European AQI bands (Good 0-20, Fair 20-40, Moderate 40-60, Poor 60-80,
// Very Poor 80-100, Extremely Poor 100+), mapped 1:1 onto the same 6-level naming
// used for the official Indice ATMO so the two scales read consistently on the
// dashboard -- this fallback is used ONLY for dates the official ATMO historical
// record has no data for (2024), and is always tagged aq_source:"estimated".
const EAQI_TIER_MAP = [[20, "Good"], [40, "Moderate"], [60, "Degraded"], [80, "Poor"], [100, "Very Poor"]];
function eaqiTier(eaqi) {
  if (eaqi === null || eaqi === undefined) return null;
  for (const [threshold, tier] of EAQI_TIER_MAP) {
    if (eaqi < threshold) return tier;
  }
  return "Extremely Poor";
}

async function fallbackHistoricalEaqi(lat, lon, targetDate) {
  const params = qs({
    latitude: lat, longitude: lon, start_date: targetDate, end_date: targetDate,
    hourly: "european_aqi", timezone: "auto",
  });
  try {
    const data = await fetchJson(`https://air-quality-api.open-meteo.com/v1/air-quality?${params}`);
    const values = (data.hourly && data.hourly.european_aqi || []).filter((v) => v !== null && v !== undefined);
    if (!values.length) return null;
    return Math.max(...values);
  } catch (e) {
    return null;
  }
}

async function fetchTodayWeather(lat, lon) {
  const params = qs({
    latitude: lat, longitude: lon, daily: "temperature_2m_max,temperature_2m_min",
    temperature_unit: "fahrenheit", timezone: "auto", forecast_days: "1",
  });
  const weather = await fetchJson(`https://api.open-meteo.com/v1/forecast?${params}`);
  return [weather.daily.temperature_2m_max[0], weather.daily.temperature_2m_min[0]];
}

async function fetchHistoricalWeatherRange(lat, lon, startDate, endDate) {
  const params = qs({
    latitude: lat, longitude: lon, start_date: startDate, end_date: endDate,
    daily: "temperature_2m_max,temperature_2m_min", temperature_unit: "fahrenheit", timezone: "auto",
  });
  const weather = await fetchJson(`https://archive-api.open-meteo.com/v1/archive?${params}`);
  const byDate = {};
  weather.daily.time.forEach((isoDate, i) => {
    byDate[isoDate] = {
      highF: weather.daily.temperature_2m_max[i],
      lowF: weather.daily.temperature_2m_min[i],
    };
  });
  return byDate;
}

async function buildPoint(townDef) {
  const town = townDef.town;
  const aq = await currentAirQuality(town);
  const [highF, lowF] = await fetchTodayWeather(townDef.lat, townDef.lon);

  const hist2025 = await fetchHistoricalWeatherRange(townDef.lat, townDef.lon, "2025-09-01", "2025-09-15");
  const hist2024 = await fetchHistoricalWeatherRange(townDef.lat, townDef.lon, "2024-09-01", "2024-09-15");
  const histWeather = { ...hist2025, ...hist2024 };

  const historicalDates = [];
  for (const d of HISTORICAL_DATES) {
    const codeQual = await historicalAqForTown(town, d);
    let tier = tierForCode(codeQual);
    let aqSource = tier !== null ? "official" : null;
    if (tier === null) {
      const eaqi = await fallbackHistoricalEaqi(townDef.lat, townDef.lon, d);
      tier = eaqiTier(eaqi);
      if (tier !== null) aqSource = "estimated";
    }
    const w = histWeather[d] || {};
    historicalDates.push({
      date: d,
      highF: w.highF !== undefined ? w.highF : null,
      lowF: w.lowF !== undefined ? w.lowF : null,
      code_qual: codeQual,
      tier,
      aq_source: aqSource,
      severity: TIER_SEVERITY[tier] || null,
    });
  }

  return {
    ride_day: townDef.ride_day,
    town,
    lat: townDef.lat,
    lon: townDef.lon,
    air_quality: {
      code_qual: aq.code_qual,
      tier: aq.tier,
      label_fr: aq.label_fr,
      severity: TIER_SEVERITY[aq.tier] || null,
      color: TIER_COLOR[aq.tier] || null,
      zone_type: aq.zone_type,
      as_of: aq.as_of,
    },
    todayHighF: highF,
    todayLowF: lowF,
    historicalDates,
  };
}

const points = [];
for (const townDef of TOWNS) {
  points.push(await buildPoint(townDef));
}

const output = {
  generatedAt: new Date().toISOString(),
  route: "BOD-NTE ALT",
  historical_dates: HISTORICAL_DATES,
  historical_data_status:
    "Current and historical Air Quality (air_quality.tier / historicalDates[].tier) are real, live data from the official French Indice ATMO (admindata.atmo-france.org for current, data.atmo-france.org historical WFS for the 4 comparison dates), queried by each town's INSEE commune code first, EPCI (intercommunal) code as a fallback. code_qual 7 ('Evenement') is a genuine official pollution-episode alert flag, shown as a distinct 'Alert' state, not folded into Good/Degraded/Poor severity. Today's high/low and historical temperature are real, live data from the Open-Meteo Forecast API and Historical Weather API. Where the official ATMO historical WFS has no record for a date (2024, confirmed never backfilled nationally for these AASQAs), historicalDates[].tier falls back to Open-Meteo's Air Quality API (European AQI) and is tagged aq_source:'estimated' rather than 'official' so the two are not conflated. RD00 (Bordeaux) is the arrival-day baseline, not a ride day; RD01-RD09 are the 9 actual ride days, each keyed to its end town. Generated automatically by n8n workflow v0002.ALT_BOD-NTE_AirQualityTemperatureConnector on a 12-hour schedule (America/Los_Angeles), from Hetzner, without Mac involvement.",
  points,
};

return [{ json: output }];

const output = $input.first().json;
const errors = [];

if (!output || typeof output !== 'object') errors.push('output is not an object');
if (!Array.isArray(output.points)) errors.push('points is not an array');
if (Array.isArray(output.points) && output.points.length !== 10) errors.push(`expected 10 points, got ${output.points.length}`);

const expectedRideDays = ['RD00','RD01','RD02','RD03','RD04','RD05','RD06','RD07','RD08','RD09'];
const foundRideDays = Array.isArray(output.points) ? output.points.map(p => p.ride_day) : [];
for (const rd of expectedRideDays) {
  if (!foundRideDays.includes(rd)) errors.push(`missing ride day ${rd}`);
}

const VALID_TIERS = ['Good', 'Moderate', 'Degraded', 'Poor', 'Very Poor', 'Extremely Poor', 'Alert'];

if (Array.isArray(output.points)) {
  for (const p of output.points) {
    if (typeof p.todayHighF !== 'number' || p.todayHighF < -40 || p.todayHighF > 130) {
      errors.push(`${p.ride_day} todayHighF implausible or missing: ${p.todayHighF}`);
    }
    if (typeof p.todayLowF !== 'number' || p.todayLowF < -40 || p.todayLowF > 130) {
      errors.push(`${p.ride_day} todayLowF implausible or missing: ${p.todayLowF}`);
    }
    if (p.todayHighF !== undefined && p.todayLowF !== undefined && typeof p.todayHighF === 'number' && typeof p.todayLowF === 'number' && p.todayHighF < p.todayLowF) {
      errors.push(`${p.ride_day} todayHighF < todayLowF`);
    }
    if (!p.air_quality || (p.air_quality.tier === undefined)) {
      errors.push(`${p.ride_day} missing air_quality.tier field`);
    } else if (p.air_quality.tier !== null && !VALID_TIERS.includes(p.air_quality.tier)) {
      errors.push(`${p.ride_day} air_quality.tier has unexpected value: ${p.air_quality.tier}`);
    }
    if (!Array.isArray(p.historicalDates) || p.historicalDates.length !== 4) {
      errors.push(`${p.ride_day} historicalDates missing or wrong length`);
    } else {
      for (const h of p.historicalDates) {
        if (h.tier !== null && h.tier !== undefined && !VALID_TIERS.includes(h.tier)) {
          errors.push(`${p.ride_day} historicalDates[${h.date}] tier has unexpected value: ${h.tier}`);
        }
      }
    }
  }
}

if (!output.historical_dates || output.historical_dates.length !== 4) errors.push('historical_dates missing or wrong length');
if (!output.generatedAt) errors.push('generatedAt missing');
if (!output.route) errors.push('route missing');

const valid = errors.length === 0;
return [{ json: { valid, errors, output } }];

const ctx = this;
const output = $input.first().json.output;
const jsonText = JSON.stringify(output, null, 2);
const buffer = Buffer.from(jsonText, 'utf-8');
const binary = await ctx.helpers.prepareBinaryData(buffer, 'latest.json', 'application/json');
return [{ json: { output, generatedAt: output.generatedAt }, binary: { data: binary } }];

const item = $input.first().json;
const stdout = item.stdout || '';
const stderr = item.stderr || '';
const exitCode = item.exitCode !== undefined ? item.exitCode : (item.exitCode === 0 ? 0 : 1);
const urlMatch = stdout.match(/https?:\/\/[a-z0-9.\-]*\.pages\.dev/i);
const deploymentUrl = urlMatch ? urlMatch[0] : null;
const success = exitCode === 0;
return [{ json: { deploySuccess: success, exitCode, stdout, stderr, deploymentUrl } }];

const ctx = this;
const deployInfo = $('Parse Deploy Result').first().json;
const stagedOutput = $('Prepare Binary').first().json.output;
const stagedGeneratedAt = stagedOutput.generatedAt;

const MAX_ATTEMPTS = 6;
const DELAY_MS = 5000;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

let live = null;
let lastError = null;
let attempts = 0;

for (let i = 0; i < MAX_ATTEMPTS; i++) {
  attempts = i + 1;
  try {
    live = await ctx.helpers.httpRequest({
      method: 'GET',
      url: `https://airqual-bod-nantes.biketourfrance.net/latest.json?cachebust=${Date.now()}`,
      json: true,
      timeout: 15000,
    });
    if (live && live.generatedAt === stagedGeneratedAt) break;
  } catch (e) {
    lastError = e && e.message ? e.message : String(e);
    live = null;
  }
  if (i < MAX_ATTEMPTS - 1) await sleep(DELAY_MS);
}

const liveGeneratedAt = live ? live.generatedAt : null;
const livePointCount = live && Array.isArray(live.points) ? live.points.length : 0;
const matches = liveGeneratedAt === stagedGeneratedAt;

return [{ json: {
  liveVerified: matches && livePointCount === 10,
  liveGeneratedAt,
  stagedGeneratedAt,
  livePointCount,
  attemptsUsed: attempts,
  lastError,
  deploymentUrl: deployInfo.deploymentUrl,
} }];

const validation = $('Validate Output').first().json;
const deploy = $('Parse Deploy Result').first().json;
const verify = $('Compare Live Data').first().json;

return [{ json: {
  project: 'BOD-Nantes Simple Dash (Bordeaux to Nantes)',
  workflowVersion: 'v0002.ALT_BOD-NTE_AirQualityTemperatureConnector',
  executionTime: new Date().toISOString(),
  dataAcquisitionStatus: 'success',
  validationStatus: validation.valid ? 'passed' : 'failed',
  stagingStatus: 'written',
  deploymentStatus: deploy.deploySuccess ? 'success' : 'failed',
  deploymentUrl: verify.deploymentUrl || deploy.deploymentUrl,
  liveVerificationStatus: verify.liveVerified ? 'passed' : 'failed',
  macRequired: false,
  errorDetails: null,
  overallStatus: (validation.valid && deploy.deploySuccess && verify.liveVerified) ? 'SUCCESS' : 'FAILED_POST_DEPLOY_CHECK',
} }];

// n8n Code node: "Fetch Dashboard Data"
// Port of BTF_local_CDM_STATUS_PAGE_PROJECT_ALT_BOD_NANTES/scripts/fetch_bod_nantes_dashboard_data.py into n8n.
// Input: one item from "Atmo Login" with json.token (bearer token).
// Output: one item, json = the full latest.json-shaped object.

