function asString(value) {
  return value === undefined || value === null ? '' : String(value);
}

function uniqueValues(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function normalizeEmail(value) {
  return asString(value).trim().toLowerCase();
}

function normalizeDirectiveKey(value) {
  return asString(value).trim().toLowerCase().replace(/[\s_]+/g, '-');
}

function parseEmailObjects(rawValue) {
  const text = asString(rawValue);
  const out = [];
  const seen = new Set();
  const angleRegex = /([^<>,\n\r]*?)<\s*([A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})\s*>/gi;
  let match;

  while ((match = angleRegex.exec(text)) !== null) {
    const displayName = asString(match[1]).replace(/^["']|["']$/g, '').trim();
    const email = normalizeEmail(match[2]);
    if (!email || seen.has(email)) continue;
    seen.add(email);
    out.push({ email, displayName });
  }

  const bareRegex = /[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}/gi;
  while ((match = bareRegex.exec(text)) !== null) {
    const email = normalizeEmail(match[0]);
    if (!email || seen.has(email)) continue;
    seen.add(email);
    out.push({ email, displayName: '' });
  }

  return out;
}

function headerValues(headers, name) {
  if (!Array.isArray(headers)) return [];
  const target = asString(name).toLowerCase();
  return headers
    .filter((h) => asString(h?.name).toLowerCase() === target)
    .map((h) => asString(h?.value).trim())
    .filter(Boolean);
}

function firstHeaderValue(headers, name) {
  return headerValues(headers, name)[0] || '';
}

function headerAddressObjects(headers, name) {
  return headerValues(headers, name).flatMap(parseEmailObjects);
}

function headerMap(headers) {
  const map = {};
  if (!Array.isArray(headers)) return map;
  for (const h of headers) {
    const name = asString(h?.name).trim();
    const value = asString(h?.value).trim();
    if (!name) continue;
    if (!map[name]) map[name] = [];
    if (value) map[name].push(value);
  }
  return map;
}

function walkParts(part) {
  if (!part || typeof part !== 'object') return [];
  const queue = [part];
  const out = [];
  while (queue.length) {
    const current = queue.shift();
    out.push(current);
    if (Array.isArray(current.parts)) queue.unshift(...current.parts);
  }
  return out;
}

function decodeBase64Url(data) {
  try {
    let b64 = asString(data).replace(/-/g, '+').replace(/_/g, '/');
    while (b64.length % 4) b64 += '=';
    return Buffer.from(b64, 'base64').toString('utf8');
  } catch (error) {
    return '';
  }
}

function extractBodyText(payload, fallbackRaw) {
  if (asString(fallbackRaw.bodyText).trim()) return asString(fallbackRaw.bodyText);
  const parts = walkParts(payload);
  for (const part of parts) {
    if (part?.mimeType === 'text/plain' && part?.body?.data) return decodeBase64Url(part.body.data);
  }
  for (const part of parts) {
    if (part?.body?.data) return decodeBase64Url(part.body.data);
  }
  if (payload?.body?.data) return decodeBase64Url(payload.body.data);
  return '';
}

function domainOf(email) {
  return normalizeEmail(email).split('@')[1] || '';
}

function isInternalAddress(email) {
  const domain = domainOf(email);
  return Array.isArray(config.internalDomains) && config.internalDomains.map(normalizeEmail).includes(domain);
}

function contactIntakeAliasInfo(email) {
  const normalized = normalizeEmail(email);
  const aliases = config.contactIntakeAliases || {};
  if (aliases[normalized]) {
    return {
      email: normalized,
      relationship: aliases[normalized].relationship || '',
      aliasType: aliases[normalized].aliasType || 'neutral',
      isContactIntakeAlias: true
    };
  }
  if (normalized === normalizeEmail(config.contactIntakeAlias)) {
    return {
      email: normalized,
      relationship: '',
      aliasType: 'neutral',
      isContactIntakeAlias: true
    };
  }
  return {
    email: normalized,
    relationship: '',
    aliasType: '',
    isContactIntakeAlias: false
  };
}

function isContactIntakeAlias(email) {
  return Boolean(contactIntakeAliasInfo(email).isContactIntakeAlias);
}

function findFirstContactIntakeAlias(objects) {
  for (const obj of objects || []) {
    const info = contactIntakeAliasInfo(obj?.email);
    if (info.isContactIntakeAlias) return info;
  }
  return { email: '', relationship: '', aliasType: '', isContactIntakeAlias: false };
}

function relationshipAliasValue(value) {
  const text = asString(value).trim().toLowerCase();
  if (!text) return '';
  const map = {
    '+rider': 'Rider',
    'rider': 'Rider',
    '+partner': 'Partner',
    'partner': 'Partner',
    '+h': 'Hospitality',
    'h': 'Hospitality',
    'hospitality': 'Hospitality',
    '+supporter': 'Supporter',
    'supporter': 'Supporter'
  };
  return map[text] || '';
}

function isMailboxOwner(email) {
  return normalizeEmail(email) === normalizeEmail(config.mailboxOwnerEmail);
}

function externalAddressObjects(objects) {
  return (objects || []).filter((o) =>
    o?.email &&
    !isInternalAddress(o.email) &&
    !isContactIntakeAlias(o.email)
  );
}

function cleanRelationshipValue(value) {
  const text = asString(value).trim();
  if (!text) return '';
  const aliasValue = relationshipAliasValue(text);
  if (aliasValue) return aliasValue;
  const allowed = Array.isArray(config.allowedRelationshipTypes) ? config.allowedRelationshipTypes : [];
  const match = allowed.find((option) => option.toLowerCase() === text.toLowerCase());
  return match || text;
}

function extractLeadingDirectives(bodyText) {
  const lines = asString(bodyText).split(/\r?\n/);
  const keptLines = [...lines];
  const parsedDirectives = [];
  const unknownDirectives = [];
  const contactNotes = [];
  let company = '';
  let relationship = '';
  let phone = '';

  let i = 0;
  while (i < keptLines.length && !asString(keptLines[i]).trim()) i++;

  while (i < keptLines.length) {
    const line = asString(keptLines[i]).trim();
    if (!line) {
      i++;
      continue;
    }

    const bracket = line.match(/^\[\[\s*([\s\S]*?)\s*\]\]$/);
    if (!bracket) break;

    const rawContent = asString(bracket[1]).trim();
    const keyValue = rawContent.match(/^([A-Za-z0-9 _-]+)\s*:\s*([\s\S]*)$/);
    const key = keyValue ? normalizeDirectiveKey(keyValue[1]) : 'contact-note';
    const value = keyValue ? asString(keyValue[2]).trim() : rawContent;
    const normalized = { raw: line, key, value };

    if (['contact-note', 'note'].includes(key)) {
      contactNotes.push(value);
      parsedDirectives.push({ ...normalized, canonicalKey: 'contact-note' });
    } else if (['company', 'account', 'organization', 'organisation', 'org'].includes(key)) {
      company = value;
      parsedDirectives.push({ ...normalized, canonicalKey: 'company' });
    } else if (['relationship', 'relationship-type', 'type', 'class', 'contact-type'].includes(key)) {
      relationship = cleanRelationshipValue(value);
      parsedDirectives.push({ ...normalized, canonicalKey: 'relationship' });
    } else if (['phone', 'mobile', 'mobile-phone'].includes(key)) {
      phone = value;
      parsedDirectives.push({ ...normalized, canonicalKey: 'phone' });
    } else {
      unknownDirectives.push(normalized);
      parsedDirectives.push({ ...normalized, canonicalKey: 'unknown' });
    }

    keptLines.splice(i, 1);
    while (i < keptLines.length && !asString(keptLines[i]).trim()) {
      keptLines.splice(i, 1);
    }
  }

  return {
    contactNote: contactNotes.join('\n').trim(),
    company: company.trim(),
    relationship: relationship.trim(),
    phone: phone.trim(),
    parsedDirectives,
    unknownDirectives,
    cleanedBodyText: keptLines.join('\n').replace(/^\s+/, '')
  };
}

function stripSubjectPrefixes(value) {
  return asString(value).replace(/^((re|fwd|fw)\s*:\s*)+/i, '').replace(/\s+/g, ' ').trim();
}

function looksForwarded(subject, bodyText) {
  return /^(fwd|fw):/i.test(asString(subject)) ||
    /forwarded message|begin forwarded message|original message/i.test(asString(bodyText));
}

function headerLineValue(lines, key) {
  const prefix = asString(key).toLowerCase() + ':';
  let collecting = false;
  let value = '';

  for (const rawLine of lines) {
    const line = asString(rawLine);
    const trimmed = line.trim();

    if (!trimmed) {
      if (collecting) break;
      continue;
    }

    if (trimmed.toLowerCase().startsWith(prefix)) {
      collecting = true;
      value = trimmed.slice(prefix.length).trim();
      continue;
    }

    if (collecting) {
      if (/^[A-Za-z-]+:\s*/.test(trimmed)) break;
      value += ' ' + trimmed;
    }
  }

  return value.trim();
}

function parseForwardBlocks(text) {
  const lines = asString(text).split(/\r?\n/);
  const markerRegex = /forwarded message|begin forwarded message|original message/i;
  const markerIndexes = [];

  for (let i = 0; i < lines.length; i++) {
    if (markerRegex.test(lines[i])) markerIndexes.push(i);
  }

  const blocks = [];

  for (let i = 0; i < markerIndexes.length; i++) {
    const start = markerIndexes[i] + 1;
    const end = i + 1 < markerIndexes.length ? markerIndexes[i + 1] : lines.length;
    const slice = lines.slice(start, end);
    const headerLines = [];

    for (const line of slice) {
      if (!asString(line).trim()) {
        if (headerLines.length > 0) break;
        continue;
      }
      headerLines.push(line);
      if (headerLines.length >= 30) break;
    }

    const fromRaw = headerLineValue(headerLines, 'From');
    const senderRaw = headerLineValue(headerLines, 'Sender');
    const replyToRaw = headerLineValue(headerLines, 'Reply-To');
    const toRaw = headerLineValue(headerLines, 'To');
    const ccRaw = headerLineValue(headerLines, 'Cc');

    blocks.push({
      markerLine: asString(lines[markerIndexes[i]]).trim(),
      from: parseEmailObjects(fromRaw)[0] || { email: '', displayName: '' },
      sender: parseEmailObjects(senderRaw)[0] || { email: '', displayName: '' },
      replyTo: parseEmailObjects(replyToRaw)[0] || { email: '', displayName: '' },
      to: parseEmailObjects(toRaw),
      cc: parseEmailObjects(ccRaw),
      subject: headerLineValue(headerLines, 'Subject'),
      date: headerLineValue(headerLines, 'Date'),
      rawHeaderLines: headerLines
    });
  }

  return blocks;
}

function titleCaseToken(value) {
  const text = asString(value).trim();
  if (!text) return '';
  return text.charAt(0).toUpperCase() + text.slice(1).toLowerCase();
}

function parseNameFromCandidate(candidate) {
  const displayName = asString(candidate.displayName)
    .replace(/^["']|["']$/g, '')
    .replace(/\s+/g, ' ')
    .trim();

  let source = 'display_name';
  let parts = displayName
    .split(/\s+/)
    .filter(Boolean)
    .filter((p) => !/@/.test(p));

  if (parts.length < 2) {
    source = 'email_local_part';
    const local = normalizeEmail(candidate.email).split('@')[0] || '';
    parts = local.replace(/[._+\-]+/g, ' ').split(/\s+/).filter(Boolean);
  }

  if (parts.length === 0) {
    return { firstName: '', lastName: '', nameSource: source, nameConfidence: 'none' };
  }

  if (parts.length === 1) {
    return {
      firstName: titleCaseToken(parts[0]),
      lastName: '',
      nameSource: source,
      nameConfidence: 'low'
    };
  }

  return {
    firstName: titleCaseToken(parts[0]),
    lastName: parts.slice(1).map(titleCaseToken).join(' '),
    nameSource: source,
    nameConfidence: source === 'display_name' ? 'high' : 'medium'
  };
}

function chooseCandidate(context) {
  const reasons = [];
  const evidence = context.evidence;

  if (context.isAutoGenerated) {
    return {
      decision: 'ignore_or_manual_review',
      candidate: null,
      source: '',
      confidence: 'none',
      reasons: ['auto_generated_or_calendar_message']
    };
  }

  if (context.intakeMode === 'forward_to_nc') {
    if (!context.detectedAsForwarded) {
      return {
        decision: 'manual_review',
        candidate: null,
        source: '',
        confidence: 'none',
        reasons: ['direct_to_nc_but_no_forwarded_message_detected']
      };
    }

    const block = context.forwardedBlocks[0] || null;
    if (!block) {
      return {
        decision: 'manual_review',
        candidate: null,
        source: '',
        confidence: 'none',
        reasons: ['forwarded_marker_without_parseable_forwarded_headers']
      };
    }

    const from = block.from?.email ? block.from : (block.sender?.email ? block.sender : block.replyTo);
    if (from?.email && !isInternalAddress(from.email) && !isContactIntakeAlias(from.email)) {
      return {
        decision: 'dry_run_preview',
        candidate: from,
        source: 'forwarded_from',
        confidence: 'high',
        reasons
      };
    }

    const externalForwardedRecipients = externalAddressObjects([...(block.to || []), ...(block.cc || [])]);
    const uniqueExternal = [];
    const seen = new Set();
    for (const obj of externalForwardedRecipients) {
      if (seen.has(obj.email)) continue;
      seen.add(obj.email);
      uniqueExternal.push(obj);
    }

    if ((from?.email && (isInternalAddress(from.email) || isMailboxOwner(from.email))) && uniqueExternal.length === 1) {
      return {
        decision: 'dry_run_preview',
        candidate: uniqueExternal[0],
        source: 'forwarded_to_when_forwarded_from_internal',
        confidence: 'high',
        reasons
      };
    }

    if (uniqueExternal.length > 1) {
      return {
        decision: 'manual_review',
        candidate: null,
        source: 'forwarded_recipients',
        confidence: 'low',
        reasons: ['multiple_external_forwarded_recipients']
      };
    }

    return {
      decision: 'manual_review',
      candidate: null,
      source: '',
      confidence: 'none',
      reasons: ['no_confident_external_forwarded_candidate']
    };
  }

  if (context.intakeMode === 'bcc_to_nc') {
    const externalTopRecipients = externalAddressObjects([...(evidence.topLevelToObjects || []), ...(evidence.topLevelCcObjects || [])]);
    const uniqueExternal = [];
    const seen = new Set();
    for (const obj of externalTopRecipients) {
      if (seen.has(obj.email)) continue;
      seen.add(obj.email);
      uniqueExternal.push(obj);
    }

    if (uniqueExternal.length === 1) {
      return {
        decision: 'dry_run_preview',
        candidate: uniqueExternal[0],
        source: 'top_level_to_cc_bcc_mode',
        confidence: 'high',
        reasons
      };
    }

    if (uniqueExternal.length > 1) {
      return {
        decision: 'manual_review',
        candidate: null,
        source: 'top_level_to_cc_bcc_mode',
        confidence: 'low',
        reasons: ['multiple_external_top_level_recipients']
      };
    }

    return {
      decision: 'manual_review',
      candidate: null,
      source: '',
      confidence: 'none',
      reasons: ['no_external_top_level_recipient_for_bcc_mode']
    };
  }

  return {
    decision: 'manual_review',
    candidate: null,
    source: '',
    confidence: 'none',
    reasons: ['message_does_not_match_contact_intake_alias_rules']
  };
}

const payload = raw.payload || raw.data?.payload || raw.body?.payload || {};
const headers = Array.isArray(payload.headers)
  ? payload.headers
  : (Array.isArray(raw.headers) ? raw.headers : []);

const bodyTextOriginal = extractBodyText(payload, raw);
const directives = extractLeadingDirectives(bodyTextOriginal);
const bodyText = directives.cleanedBodyText;

const subject = firstHeaderValue(headers, 'Subject') || asString(raw.subject);
const topLevelFromObjects = headerAddressObjects(headers, 'From');
const topLevelToObjects = headerAddressObjects(headers, 'To');
const topLevelCcObjects = headerAddressObjects(headers, 'Cc');
const topLevelBccObjects = headerAddressObjects(headers, 'Bcc');
const deliveredToObjects = headerAddressObjects(headers, 'Delivered-To');
const xForwardedToObjects = headerAddressObjects(headers, 'X-Forwarded-To');
const sender = firstHeaderValue(headers, 'Sender');
const autoSubmitted = firstHeaderValue(headers, 'Auto-Submitted');

const allDirectAliasObjects = [
  ...topLevelToObjects,
  ...topLevelCcObjects,
  ...deliveredToObjects,
  ...xForwardedToObjects
];

const directAliasInfo = findFirstContactIntakeAlias(allDirectAliasObjects);
const bccAliasInfo = findFirstContactIntakeAlias(topLevelBccObjects);
const directToNc = Boolean(directAliasInfo.isContactIntakeAlias);
const bccToNc = Boolean(bccAliasInfo.isContactIntakeAlias);
const activeAliasInfo = directToNc ? directAliasInfo : (bccToNc ? bccAliasInfo : { email: '', relationship: '', aliasType: '', isContactIntakeAlias: false });
const aliasRelationship = activeAliasInfo.relationship || '';
const aliasRelationshipSource = aliasRelationship ? 'intake_alias' : '';
const detectedAsForwarded = looksForwarded(subject, bodyTextOriginal);
const isAutoGenerated =
  /auto-generated|auto-replied/i.test(autoSubmitted) ||
  /calendar-notification@google\.com/i.test(sender) ||
  /google calendar/i.test(sender);

let intakeMode = 'unresolved';
if (directToNc && detectedAsForwarded) {
  intakeMode = 'forward_to_nc';
} else if (bccToNc && !detectedAsForwarded) {
  intakeMode = 'bcc_to_nc';
} else if (directToNc) {
  intakeMode = 'forward_to_nc';
} else if (bccToNc) {
  intakeMode = 'bcc_to_nc';
}

const forwardedBlocks = parseForwardBlocks(bodyText);

const evidence = {
  rawHeaderNames: headers.map((h) => h?.name).filter(Boolean),
  rawHeadersByName: headerMap(headers),
  contactIntakeAlias: activeAliasInfo.email || '',
  aliasRelationship,
  aliasRelationshipSource,
  subject,
  subjectClean: stripSubjectPrefixes(subject),
  topLevelFrom: topLevelFromObjects[0] || { email: '', displayName: '' },
  topLevelToObjects,
  topLevelCcObjects,
  topLevelBccObjects,
  topLevelTo: topLevelToObjects.map((o) => o.email),
  topLevelCc: topLevelCcObjects.map((o) => o.email),
  topLevelBcc: topLevelBccObjects.map((o) => o.email),
  deliveredTo: deliveredToObjects.map((o) => o.email),
  xForwardedTo: xForwardedToObjects.map((o) => o.email),
  sender,
  autoSubmitted,
  forwardedBlocks,
  forwardedFrom: forwardedBlocks[0]?.from || { email: '', displayName: '' },
  forwardedTo: (forwardedBlocks[0]?.to || []).map((o) => o.email),
  forwardedCc: (forwardedBlocks[0]?.cc || []).map((o) => o.email)
};

const context = {
  intakeMode,
  detectedAsForwarded,
  forwardedBlocks,
  evidence,
  isAutoGenerated
};

const candidateDecision = chooseCandidate(context);
const manualReviewReasons = [...(candidateDecision.reasons || [])];
const allowedRelationshipTypes = Array.isArray(config.allowedRelationshipTypes) ? config.allowedRelationshipTypes : [];
const directiveRelationship = directives.relationship || '';
const relationshipConflict = Boolean(aliasRelationship && directiveRelationship && aliasRelationship !== directiveRelationship);
const effectiveRelationship = directiveRelationship || aliasRelationship || '';
const relationshipAllowed = effectiveRelationship
  ? allowedRelationshipTypes.some((option) => option.toLowerCase() === effectiveRelationship.toLowerCase())
  : false;

if (directives.unknownDirectives.length > 0) {
  manualReviewReasons.push('unknown_contact_intake_directive');
}

if (directiveRelationship && !allowedRelationshipTypes.some((option) => option.toLowerCase() === directiveRelationship.toLowerCase())) {
  manualReviewReasons.push('relationship_directive_not_in_allowed_list');
}

if (relationshipConflict) {
  manualReviewReasons.push('relationship_alias_directive_conflict');
}

let candidate = {
  emailAddress: '',
  firstName: '',
  lastName: '',
  source: candidateDecision.source || '',
  confidence: candidateDecision.confidence || 'none',
  nameSource: '',
  nameConfidence: ''
};

if (candidateDecision.candidate?.email) {
  const parsedName = parseNameFromCandidate(candidateDecision.candidate);
  candidate = {
    emailAddress: candidateDecision.candidate.email,
    firstName: parsedName.firstName,
    lastName: parsedName.lastName,
    source: candidateDecision.source,
    confidence: candidateDecision.confidence,
    nameSource: parsedName.nameSource,
    nameConfidence: parsedName.nameConfidence
  };

  if (!candidate.lastName) {
    manualReviewReasons.push('missing_reliable_last_name');
  }
}

let decision = candidateDecision.decision;
if (candidate.emailAddress && !candidate.lastName) {
  decision = 'manual_review';
}
if (effectiveRelationship && !relationshipAllowed) {
  decision = 'manual_review';
}
if (relationshipConflict) {
  decision = 'manual_review';
}

const sourceGmailMessageId = asString(raw.id || raw.gmailMessageId || raw.data?.id || raw.body?.id);
const sourceGmailThreadId = asString(raw.threadId || raw.gmailThreadId || raw.data?.threadId || raw.body?.threadId);

return {
    workflowName: config.workflowName || 'v10c.H.Contact_Intake.DEV.ONE_CONTACT_WRITE_TEST.WRITE_FLAG_PROPAGATION_FIX',
    mode: config.mode || 'dry_run',
    write_allowed: Boolean(config.write_allowed),
    read_allowed: Boolean(config.read_allowed),
    decision,
    intakeMode,
    intakeAlias: {
      email: activeAliasInfo.email || '',
      aliasType: activeAliasInfo.aliasType || '',
      relationship: aliasRelationship || '',
      relationshipSource: aliasRelationshipSource || ''
    },
    candidate,
    privateContactNote: directives.contactNote,
    privateContactNoteSyntax: directives.contactNote ? 'leading_bracket_directive' : '',
    directives: {
      parsedDirectives: directives.parsedDirectives,
      unknownDirectives: directives.unknownDirectives,
      contactNote: directives.contactNote,
      company: directives.company,
      relationship: directives.relationship,
      phone: directives.phone
    },
    companyCandidate: {
      name: directives.company,
      source: directives.company ? 'explicit_directive' : '',
      confidence: directives.company ? 'operator_provided' : 'none',
      accountLookupAllowed: Boolean(config.allow_account_link),
      accountCreateAllowed: Boolean(config.allow_account_create)
    },
    relationshipCandidate: {
      value: effectiveRelationship,
      source: directiveRelationship ? 'explicit_directive' : (aliasRelationship ? 'intake_alias' : ''),
      confidence: effectiveRelationship ? (directiveRelationship ? 'operator_provided' : 'operator_selected_alias') : 'none',
      allowedValues: allowedRelationshipTypes,
      isAllowed: Boolean(effectiveRelationship && relationshipAllowed),
      aliasRelationship,
      directiveRelationship,
      relationshipConflict
    },
    phoneCandidate: {
      value: directives.phone,
      source: directives.phone ? 'explicit_directive' : '',
      confidence: directives.phone ? 'operator_provided' : 'none'
    },
    duplicateSearchPlan: {
      entity: 'Contact',
      attribute: 'emailAddress',
      value: candidate.emailAddress || '',
      queryShape: candidate.emailAddress
        ? `GET /api/v1/Contact?where[0][type]=equals&where[0][attribute]=emailAddress&where[0][value]=${candidate.emailAddress}`
        : ''
    },
    accountSearchPlan: {
      entity: 'Account',
      attribute: 'name',
      value: directives.company || '',
      queryShape: directives.company
        ? `GET /api/v1/Account?where[0][type]=equals&where[0][attribute]=name&where[0][value]=${encodeURIComponent(directives.company)}`
        : ''
    },
    manualReviewReasons: uniqueValues(manualReviewReasons),
    sourceEvidence: {
      gmailMessageId: sourceGmailMessageId,
      gmailThreadId: sourceGmailThreadId,
      topLevelFrom: evidence.topLevelFrom,
      topLevelTo: evidence.topLevelTo,
      topLevelCc: evidence.topLevelCc,
      topLevelBcc: evidence.topLevelBcc,
      deliveredTo: evidence.deliveredTo,
      xForwardedTo: evidence.xForwardedTo,
      subject: evidence.subject,
      sender: evidence.sender,
      autoSubmitted: evidence.autoSubmitted,
      detectedAsForwarded,
      forwardedFrom: evidence.forwardedFrom,
      forwardedTo: evidence.forwardedTo,
      forwardedCc: evidence.forwardedCc,
      forwardedBlocksCount: forwardedBlocks.length,
      firstForwardedBlock: forwardedBlocks[0] || null
    },
    config,
    bodyTextPreview: bodyText.slice(0, 1000)
  };
}

return $input.all().map((item) => ({ json: processOne(item.json || {}) }));

function processOne(inputJson) {
const item = inputJson || {};
const candidate = item.candidate || {};
const config = item.config || {};
const manualReviewReasons = Array.isArray(item.manualReviewReasons) ? [...item.manualReviewReasons] : [];
const companyCandidate = item.companyCandidate || {};
const relationshipCandidate = item.relationshipCandidate || {};
const phoneCandidate = item.phoneCandidate || {};
const directives = item.directives || {};

function asString(value) {
  return value === undefined || value === null ? '' : String(value);
}

function normalizeEmail(value) {
  return asString(value).trim().toLowerCase();
}

function unique(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function emailLocalPart(email) {
  return normalizeEmail(email).split('@')[0] || '';
}

function classifyEmailLocalPart(email) {
  const local = emailLocalPart(email);
  const generic = [
    'info', 'contact', 'support', 'sales', 'hello', 'admin',
    'booking', 'bookings', 'reservation', 'reservations',
    'reception', 'accueil', 'office', 'team', 'service',
    'customerservice', 'customer-service'
  ];
  const noReply = [
    'noreply', 'no-reply', 'do-not-reply', 'donotreply',
    'notification', 'notifications', 'mailer', 'postmaster'
  ];

  if (!local) {
    return { type: 'missing', score: 0, warning: 'No email local part available.' };
  }

  if (noReply.includes(local) || /^no[-_.]?reply/.test(local) || /do[-_.]?not[-_.]?reply/.test(local)) {
    return { type: 'no_reply', score: 0, warning: 'Address appears to be an automated no-reply mailbox.' };
  }

  if (generic.includes(local)) {
    return { type: 'generic_org_inbox', score: 45, warning: 'Address may represent an organization inbox rather than a personal inbox.' };
  }

  if (/[._-]/.test(local)) {
    const parts = local.split(/[._-]+/).filter(Boolean);
    if (parts.length >= 2) return { type: 'person_like', score: 80, warning: '' };
  }

  return { type: 'unknown_or_single_token', score: 60, warning: 'Email local part is not clearly personal or organizational.' };
}

function assessNameQuality(candidate) {
  const warnings = [];
  const firstName = asString(candidate.firstName).trim();
  const lastName = asString(candidate.lastName).trim();
  const nameSource = asString(candidate.nameSource).trim();
  const nameConfidence = asString(candidate.nameConfidence).trim();
  let quality = 'missing';
  let score = 0;

  if (firstName && lastName && nameConfidence === 'high') {
    quality = 'full_name_high_confidence';
    score = 85;
  } else if (firstName && lastName && nameConfidence === 'medium') {
    quality = 'full_name_medium_confidence';
    score = 70;
  } else if (firstName && lastName) {
    quality = 'full_name_present_low_context';
    score = 60;
    warnings.push('Full name exists but confidence source is weak or unspecified.');
  } else if (firstName && !lastName) {
    quality = 'first_name_only';
    score = 35;
    warnings.push('Candidate has first name only; EspoCRM requires lastName.');
  } else {
    quality = 'missing';
    score = 0;
    warnings.push('No reliable candidate name found.');
  }

  if (/^[A-Z]\.?$/i.test(firstName)) {
    warnings.push('First name looks like an initial.');
    score = Math.min(score, 40);
  }

  return { quality, score, firstName, lastName, source: nameSource, confidence: nameConfidence, warnings };
}

function candidateEvidenceText(source) {
