async function fetchJson(url, headers, attempt) {
  attempt = attempt || 1;
  try {
    return await ctx.helpers.httpRequest({
      method: "GET",
      url,
      headers: headers || {},
      json: true,
      timeout: 30000,
    });
  } catch (e) {
    const status =
      (e && e.response && (e.response.status || e.response.statusCode)) ||
      e.statusCode || e.httpCode || e.status || undefined;
    const isTransient = status === undefined || status >= 500;
    if (isTransient && attempt < 3) {
      await sleep(1000 * attempt);
      return fetchJson(url, headers, attempt + 1);
    }
    const err = new Error(e && e.message ? e.message : String(e));
    if (status !== undefined) err.status = Number(status);
    throw err;
  }
