async function fetchJson(url, headers, attempt) {
  attempt = attempt || 1;
  try {
    return await ctx.helpers.httpRequest({
      method: "GET",
      url,
      headers: headers || {},
      json: true,
      timeout: 30000,
    });
  } catch (e) {
    const status =
      (e && e.response && (e.response.status || e.response.statusCode)) ||
      e.statusCode || e.httpCode || e.status || undefined;
    const isTransient = status === undefined || status >= 500;
    if (isTransient && attempt < 3) {
      await sleep(1000 * attempt);
      return fetchJson(url, headers, attempt + 1);
    }
    const err = new Error(e && e.message ? e.message : String(e));
    if (status !== undefined) err.status = Number(status);
    throw err;
  }
}

async function atmoQuery(zoneCode, dateEch) {
  const filt = { code_zone: { operator: "=", value: zoneCode }, date_ech: { operator: "=", value: dateEch } };
  const url = `${ATMO_BASE}${ATMO_DATA_PATH}/${encodeURIComponent(JSON.stringify(filt))}?withGeom=false`;
  try {
    const data = await fetchJson(url, { Authorization: `Bearer ${token}` });
    const feats = data.features || [];
    if (!feats.length) return null;
    return feats[0].properties;
  } catch (e) {
    if (e.status !== undefined) return null; // HTTP error (e.g. 404 no feature) treated as "no data"
    throw e; // network/timeout errors abort the run
  }
}

async function currentAirQuality(town) {
  const zones = ZONE_CODES[town];
  const today = new Date().toISOString().slice(0, 10);
  for (const [zoneType, zoneCode] of [["commune", zones.insee], ["EPCI", zones.epci]]) {
    const props = await atmoQuery(zoneCode, today);
    if (props && props.code_qual !== null && props.code_qual !== undefined) {
      return {
        code_qual: props.code_qual,
        tier: tierForCode(props.code_qual),
        label_fr: QUAL_LABEL[props.code_qual] || null,
        zone_type: zoneType,
        zone_code: zoneCode,
        as_of: props.date_maj || null,
      };
    }
  }
  return { code_qual: null, tier: null, label_fr: null, zone_type: null, zone_code: null, as_of: null };
}

function isoWeekPartition(dateStr) {
  let d = new Date(dateStr + "T00:00:00Z");
  const day = (d.getUTCDay() + 6) % 7; // Mon=0..Sun=6
  d.setUTCDate(d.getUTCDate() - day + 3); // nearest Thursday
  const year = d.getUTCFullYear();
  let firstThu = new Date(Date.UTC(year, 0, 4));
  const fDay = (firstThu.getUTCDay() + 6) % 7;
  firstThu.setUTCDate(firstThu.getUTCDate() - fDay);
  const week = 1 + Math.round((d - firstThu) / (7 * 86400000));
  return `${year}w${String(week).padStart(2, "0")}`;
}

async function historicalAirQuality(zoneCode, targetDate) {
  const partition = isoWeekPartition(targetDate);
  const filterXml =
    `<Filter><And>` +
    `<PropertyIsEqualTo><PropertyName>date_ech</PropertyName><Literal>${targetDate}</Literal></PropertyIsEqualTo>` +
    `<PropertyIsEqualTo><PropertyName>code_zone</PropertyName><Literal>${zoneCode}</Literal></PropertyIsEqualTo>` +
    `</And></Filter>`;
  const params = qs({
    SERVICE: "WFS", VERSION: "2.0.0", REQUEST: "GetFeature",
    TYPENAMES: "ind:ind_atmo_partition_week", OUTPUTFORMAT: "application/json",
    FILTER: filterXml, viewparams: `PARTITION_WEEK_ID:${partition}`,
  });
  const url = `${ATMO_WFS_BASE}?${params}`;
  try {
    const data = await fetchJson(url);
    const feats = data.features || [];
    if (!feats.length) return null;
    return feats[0].properties;
  } catch (e) {
    if (e.status !== undefined) return null;
    throw e;
  }
}

async function historicalAqForTown(town, targetDate) {
