    ride_day: townDef.ride_day,
    town,
    lat: townDef.lat,
    lon: townDef.lon,
    air_quality: {
      code_qual: aq.code_qual,
      tier: aq.tier,
      label_fr: aq.label_fr,
      severity: TIER_SEVERITY[aq.tier] || null,
      color: TIER_COLOR[aq.tier] || null,
      zone_type: aq.zone_type,
      as_of: aq.as_of,
    },
