  artifact_paths: {
    candidate: outputRoot + '/candidate/' + laneRoot + '/' + laneRoot + '_candidate_' + runStamp + '.json',
    normalized: outputRoot + '/normalized/' + laneRoot + '/' + laneRoot + '_normalized_' + runStamp + '.json',
