}));

let current = rows.find((row) => String(row.status).toLowerCase() === 'current');

if (!current) {
  current = rows
    .filter((row) => row.sequence)
    .sort((a, b) => Number(a.sequence) - Number(b.sequence))[0];
}

if (!current || current.sequence === undefined || current.sequence === null || current.sequence === '') {
