  sequence: Number(item.json.sequence),
  cycle_count: Number(item.json.cycle_count || 0),
}));

const maxSequence = Math.max(...rows.map((row) => row.sequence));
const acknowledged = rows.find((row) => row.sequence === acknowledgedSequence);

if (!acknowledged) {
  throw new Error(`No tracker row found for sequence ${acknowledgedSequence}`);
}

const nextSequence = acknowledgedSequence >= maxSequence ? 1 : acknowledgedSequence + 1;
const completingCycle = nextSequence === 1;

return rows.map((row) => {
  let status = row.status;
  let acknowledged_at = row.acknowledged_at;
  let cycle_count = row.cycle_count;

  if (row.sequence === acknowledgedSequence) {
    status = 'done';
    acknowledged_at = now;
  }

  if (completingCycle) {
    status = 'pending';
    cycle_count += 1;
  }

  if (row.sequence === nextSequence) {
    status = 'current';
  }

  return {
    json: {
      sequence: row.sequence,
      tab_title: row.tab_title,
      tab_id: row.tab_id,
      tab_url: row.tab_url,
      status,
      last_sent_at: row.last_sent_at,
