    publicationDate: item.startedAt || null,
    checkedAt,
    sourceUrl: item.sourceUrl || 'https://www.vnf.fr/vnf/avis-a-la-batellerie/',
    documentUrl: item.evidenceUrl || null,
    summary: item.effect + ' - ' + item.waterway + '. ' + noImpactWording(item.officialNoticeType),
    statusTitle: item.title,
    statusExplanation,
    statusSource: { name: sourceName, url: item.sourceUrl || item.evidenceUrl || 'https://www.vnf.fr/vnf/avis-a-la-batellerie/', official: true, checkedAt, sourceLanguage: 'fr', translationMethod: 'condensed_official_source' },
    whyItMatters: isImpactReported ? 'An official VNF notice explicitly reports towpath or public-access impact near the route corridor.' : 'An official VNF canal/waterway notice is in effect near the route corridor; this is a boat-navigation fact, not a confirmed cyclist route impact.',
    recommendedAction: 'Check VNF and official route notices before relying on canal-adjacent access near the affected section.',
    suggestedDetour: null,
