    raw: { noticeNumber: item.noticeNumber, waterway: item.waterway, effect: item.effect, evidenceText: item.evidenceText, extractionMethod: item.extractionMethod, hasCyclistTowpathMention: Boolean(item.hasCyclistTowpathMention) },
