});

return normalized.map((r) => ({ json: r }));

const config = $items('Set Connector Config')[0].json;
const fetchMetaItems = $items('Merge Fetch Meta And Parsed Notices').map((i) => i.json).filter((i) => i.recordKind === 'fetchMeta');
const parseMetaItems = $items('Merge Fetch Meta And Parsed Notices').map((i) => i.json).filter((i) => i.recordKind === 'parseMeta');
const fetchMeta = fetchMetaItems[0] || { fetchOk: false, pagesFetched: 0, pdfCandidateCount: 0, errors: ['No fetchMeta record observed'] };
const parseMeta = parseMetaItems[0] || { documentsSeen: 0, documentsProcessed: 0, documentErrors: [], noticeCount: 0 };
const normalizedNotices = $input.all().map((i) => i.json || {}).filter((i) => i.recordKind === 'officialCanalNotice');

const navigationRestrictionCount = normalizedNotices.filter((n) => n.officialNoticeType === 'navigation_restriction').length;
const maintenanceChomageCount = normalizedNotices.filter((n) => ['canal_maintenance', 'chomage_calendar'].includes(n.officialNoticeType)).length;
