// Multi-horizon mode: check one travel date at each configured offset.
// Default horizons: 14 / 28 / 42 days out (2, 4 and 6 weeks).
// Override by adding a `date_offsets` column to the CONFIG sheet, e.g. "14,28,42".
// The legacy `date_range_days` field is no longer used for scheduling horizons.
const config = $input.first().json;

function parseOffsets(raw) {
  return String(raw || '')
    .split(',')
    .map(x => parseInt(String(x).trim(), 10))
    .filter(n => Number.isFinite(n) && n > 0);
}

let offsets = parseOffsets(config.date_offsets);
if (offsets.length === 0) {
  offsets = parseOffsets(config.date_offsets_days);
}
if (offsets.length === 0) {
  offsets = [14, 28, 42];
}
offsets = Array.from(new Set(offsets)).sort((a, b) => a - b);

const tripLengthParsed = parseInt(config.trip_length_days, 10);
const tripLength = Number.isFinite(tripLengthParsed) && tripLengthParsed > 0 ? tripLengthParsed : 5;

const origins = String(config.origins || 'SEA,PAE').split(',').map(x => x.trim()).filter(Boolean);
const destination = String(config.destination || 'PHX').trim();

const items = [];
for (const offset of offsets) {
  const travelDate = new Date();
  travelDate.setDate(travelDate.getDate() + offset);
  const dateStr = travelDate.toISOString().split('T')[0];

  const returnDate = new Date(travelDate);
  returnDate.setDate(returnDate.getDate() + tripLength);
  const returnDateStr = returnDate.toISOString().split('T')[0];

  for (const origin of origins) {
    items.push({
      json: {
        departure_id: origin,
        arrival_id: destination,
        outbound_date: dateStr,
        return_date: returnDateStr,
        offset_days: offset
      }
    });
  }
}

return items;

// Extract the lowest fare from the SerpAPI Google Flights response.
// Query details come back in search_parameters, so no cross-node references needed.
const r = $input.first().json;
const sp = r.search_parameters || {};
const todayStr = new Date().toISOString().split('T')[0];

const flights = [...(r.best_flights || []), ...(r.other_flights || [])];

if (flights.length === 0) {
  return [{
    json: {
      date_checked: todayStr,
      travel_date: sp.outbound_date || 'unknown',
      origin: sp.departure_id || 'unknown',
      destination: sp.arrival_id || 'unknown',
      price: '',
      carrier: 'NO FLIGHTS FOUND',
      stops: '',
      timestamp: new Date().toISOString()
    }
  }];
}

let best = null;
for (const f of flights) {
  const price = typeof f.price === 'number' ? f.price : parseInt(String(f.price || '').replace(/[^0-9]/g, ''));
  if (!price || isNaN(price)) continue;
  if (!best || price < best.price) {
    best = {
      price: price,
      carrier: f.flights?.[0]?.airline || 'unknown',
      stops: Math.max((f.flights?.length || 1) - 1, 0)
    };
  }
}

return [{
  json: {
    date_checked: todayStr,
    travel_date: sp.outbound_date || 'unknown',
    origin: sp.departure_id || 'unknown',
    destination: sp.arrival_id || 'unknown',
    price: best ? best.price : '',
    carrier: best ? best.carrier : 'unknown',
    stops: best ? best.stops : '',
    timestamp: new Date().toISOString()
  }
}];

// Build the report using only the most recent run's rows.
// This run wrote (origins x offsets) rows, so take exactly that many from the end
// of HISTORY. Filtering by date alone can pick up leftover rows from earlier
// test runs on the same day.
const config = $('Read Config from Sheets').first().json;
const floor = parseFloat(config.absolute_floor_usd) || 400;
const origins = String(config.origins || 'SEA,PAE').split(',').map(x => x.trim()).filter(Boolean);
const todayStr = new Date().toISOString().split('T')[0];

function parseOffsets(raw) {
  return String(raw || '')
    .split(',')
    .map(x => parseInt(String(x).trim(), 10))
    .filter(n => Number.isFinite(n) && n > 0);
}

let offsets = parseOffsets(config.date_offsets);
if (offsets.length === 0) {
  offsets = parseOffsets(config.date_offsets_days);
}
if (offsets.length === 0) {
  offsets = [14, 28, 42];
}
offsets = Array.from(new Set(offsets)).sort((a, b) => a - b);

const expectedRows = origins.length * offsets.length;
const allRows = $input.all().map(i => i.json);
const rows = allRows.slice(-expectedRows);

const priced = rows
  .filter(r => r.price !== '' && r.price !== null && r.price !== undefined)
  .map(r => ({ ...r, price: Number(r.price) }))
  .filter(r => !isNaN(r.price));

const belowFloor = priced.filter(r => r.price < floor);

// Group by travel date so each horizon gets its own block.
const byDate = {};
for (const r of priced) {
  const key = String(r.travel_date || 'unknown');
  if (!byDate[key]) byDate[key] = [];
  byDate[key].push(r);
}
const dateKeys = Object.keys(byDate).sort();

function horizonLabel(dateStr) {
  const d = new Date(dateStr + 'T00:00:00Z');
  if (isNaN(d.getTime())) return '';
  const today = new Date(todayStr + 'T00:00:00Z');
  const days = Math.round((d.getTime() - today.getTime()) / 86400000);
  const weeks = Math.round(days / 7);
  return ` (~${weeks} week${weeks === 1 ? '' : 's'} out, ${days} days)`;
}

let body = `Flight Price Report – ${todayStr}\n`;
body += `================================\n\n`;

if (priced.length === 0) {
  body += `No prices were collected on this run. Check the workflow execution log.\n`;
}

if (belowFloor.length > 0) {
  const sortedDeals = [...belowFloor].sort((a, b) => a.price - b.price);
  body += `DEALS (below $${floor}):\n`;
  for (const f of sortedDeals) {
    body += `  ${f.origin} -> ${f.destination} on ${f.travel_date}: $${f.price} (${f.carrier}, ${f.stops} stops)\n`;
  }
  body += `\n`;
}

for (const key of dateKeys) {
  body += `${key}${horizonLabel(key)}:\n`;
  const sorted = [...byDate[key]].sort((a, b) => a.price - b.price);
  for (const f of sorted) {
    body += `  ${f.origin} -> ${f.destination}: $${f.price} (${f.carrier}, ${f.stops} stops)\n`;
  }
  body += `\n`;
}

if (priced.length > 0) {
  const cheapest = [...priced].sort((a, b) => a.price - b.price)[0];
  body += `Cheapest this run: ${cheapest.origin} -> ${cheapest.destination} on ${cheapest.travel_date} at $${cheapest.price} (${cheapest.carrier})\n\n`;
}

body += `---\n`;
body += `Monitoring: ${config.origins} -> ${config.destination}\n`;
body += `Horizons checked: ${offsets.join(', ')} days out | Deal floor: $${floor}\n`;
body += `Searches this run: ${expectedRows}\n`;

return [{ json: { emailBody: body, subjectDate: todayStr } }];

const rows = items.map((item, index) => ({
  ...item.json,
  _rowNumber: index + 2,
}));

let current = rows.find((row) => String(row.status).toLowerCase() === 'current');

if (!current) {
  current = rows
    .filter((row) => row.sequence)
    .sort((a, b) => Number(a.sequence) - Number(b.sequence))[0];
}

const ackBaseUrl = 'https://n8n.biketourfrance.net/webhook/fle-tab-ack';

return [{
  json: {
    ...current,
    sent_at: new Date().toISOString(),
    ack_url: `${ackBaseUrl}?sequence=${encodeURIComponent(current.sequence)}`,
  },
}];

