const remainingBlocks = contentBlocks.slice(1);
const taskTitle = (humanNextAction || subjectClean || 'Task').slice(0, 140);

const externalRecipients = uniqueValues([
  ...normalizedHeaders.to,
  ...normalizedHeaders.cc,
  ...normalizedHeaders.bcc,
].filter((addr) => !isInternalBtfAddress(addr)));
const productionCurrentContactLookupEmail = externalRecipients[0] || '';
const mailboxOwnerEmail = String('john@biketourfrance.net').trim().toLowerCase();
const fromHeader = rawHeaderValues.from[0] || raw.from || '';
const originatorEmail = firstEmail(fromHeader);
const topLevelFrom = originatorEmail;
const bodyTextForwarded = /forwarded message|begin forwarded message|original message|forwarded by/i.test(bodyText);
const subjectLooksForwarded = /^(fwd|fw):/i.test(subject) || /\bforwarded\b/i.test(subject);
const explicitOriginalSender = firstAddressFromMany(
  rawHeaderValues['x-original-from']?.[0],
  rawHeaderValues['x-original-sender']?.[0],
  rawHeaderValues['x-google-original-from']?.[0],
  rawHeaderValues['x-forwarded-from']?.[0],
  rawHeaderValues['resent-from']?.[0],
  rawHeaderValues['resent-sender']?.[0]
);

function firstAddressFromMany(...values) {
  for (const value of values) {
    const email = firstEmail(value);
    if (email) return email;
  }
  return '';
}

function dedupePreserveOrder(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function headerLineValue(lines, key) {
  const prefix = String(key || '').toLowerCase() + ':';
  for (const line of lines) {
    const trimmed = String(line || '').trim();
    if (trimmed.toLowerCase().startsWith(prefix)) {
      return trimmed.slice(prefix.length).trim();
    }
  }
  return '';
}

function parseForwardBlocks(text) {
  const lines = String(text || '').split(/\r?\n/);
  const markerRegex = /forwarded message|begin forwarded message|original message|forwarded by/i;
  const markerIndexes = [];
  for (let i = 0; i < lines.length; i += 1) {
    if (markerRegex.test(lines[i])) markerIndexes.push(i);
  }

  const blocks = [];
  for (let i = 0; i < markerIndexes.length; i += 1) {
    const start = markerIndexes[i] + 1;
    const end = i + 1 < markerIndexes.length ? markerIndexes[i + 1] : lines.length;
    const slice = lines.slice(start, end);
    const headerLines = [];
    for (const line of slice) {
      if (!String(line || '').trim()) {
        if (headerLines.length > 0) break;
        continue;
      }
      headerLines.push(line);
      if (headerLines.length >= 24) break;
    }
    blocks.push({
      markerLine: String(lines[markerIndexes[i]] || '').trim(),
      fromEmail: firstAddressFromMany(headerLineValue(headerLines, 'From')),
      senderEmail: firstAddressFromMany(headerLineValue(headerLines, 'Sender')),
      replyToEmail: firstAddressFromMany(headerLineValue(headerLines, 'Reply-To')),
      subject: headerLineValue(headerLines, 'Subject'),
      date: headerLineValue(headerLines, 'Date'),
      toEmail: firstAddressFromMany(headerLineValue(headerLines, 'To')),
      rawHeaderLines: headerLines,
    });
  }

  return blocks;
}

const forwardedBlocks = parseForwardBlocks(bodyText);
const bodyForwardCandidate = [...forwardedBlocks].reverse().find((block) => block.fromEmail || block.senderEmail || block.replyToEmail) || null;
const detectedAsForwarded = Boolean(explicitOriginalSender || bodyForwardCandidate || subjectLooksForwarded || bodyTextForwarded);

let forwardParserContactCandidateEmail = '';
let forwardParserMatchedStrategy = 'unresolved';
let forwardParserConfidence = 'not_applicable';
let winningSourceField = '';
let winningSourceValue = '';
const notes = [];

if (explicitOriginalSender) {
  forwardParserContactCandidateEmail = explicitOriginalSender;
  winningSourceField = rawHeaderValues['x-original-from']?.[0]
    ? 'x-original-from'
    : (rawHeaderValues['x-original-sender']?.[0]
      ? 'x-original-sender'
      : (rawHeaderValues['x-google-original-from']?.[0]
        ? 'x-google-original-from'
        : (rawHeaderValues['x-forwarded-from']?.[0]
          ? 'x-forwarded-from'
          : (rawHeaderValues['resent-from']?.[0] ? 'resent-from' : 'resent-sender'))));
  winningSourceValue = forwardParserContactCandidateEmail;
  forwardParserMatchedStrategy = 'gmail_forwarded_header';
  forwardParserConfidence = 'high';
  notes.push('Explicit original-sender header found in Gmail metadata.');
} else if (bodyForwardCandidate?.fromEmail || bodyForwardCandidate?.senderEmail || bodyForwardCandidate?.replyToEmail) {
  forwardParserContactCandidateEmail = bodyForwardCandidate.fromEmail || bodyForwardCandidate.senderEmail || bodyForwardCandidate.replyToEmail || '';
  winningSourceField = bodyForwardCandidate.fromEmail ? 'forwarded_body_from' : (bodyForwardCandidate.senderEmail ? 'forwarded_body_sender' : 'forwarded_body_reply_to');
  winningSourceValue = forwardParserContactCandidateEmail;
  forwardParserMatchedStrategy = forwardedBlocks.length > 1 ? 'nested_forwarded_body_block' : 'forwarded_body_block';
  forwardParserConfidence = forwardedBlocks.length > 1 ? 'medium' : 'high';
  notes.push(`Forwarded body marker(s) found: ${forwardedBlocks.length}.`);
  if (forwardedBlocks.length > 1) {
    notes.push('Multiple forwarded layers reduce certainty about the true original sender.');
  }
} else if (!detectedAsForwarded && topLevelFrom) {
  forwardParserContactCandidateEmail = topLevelFrom;
  winningSourceField = 'top_level_from';
  winningSourceValue = topLevelFrom;
  forwardParserMatchedStrategy = 'gmail_top_level_from';
  forwardParserConfidence = 'not_applicable';
  notes.push('No forwarded markers observed; top-level From is used only as a direct-message fallback.');
} else if (detectedAsForwarded) {
  forwardParserMatchedStrategy = 'forwarded_ambiguous_no_sender';
  forwardParserConfidence = 'low';
  winningSourceField = 'unresolved';
  winningSourceValue = '';
  notes.push('Forwarded cues were present but no safe original-sender candidate was extracted.');
}

const contactCandidateEmail = forwardParserContactCandidateEmail || '';
const hasHighConfidenceForwardedSender = Boolean(detectedAsForwarded && forwardParserConfidence === 'high' && contactCandidateEmail);
const mailboxOwnerSelfTask = Boolean(mailboxOwnerEmail && topLevelFrom === mailboxOwnerEmail && !detectedAsForwarded && !hasHighConfidenceForwardedSender);
const recommendedTaskContactLookupEmail = (detectedAsForwarded && forwardParserConfidence === 'high' && contactCandidateEmail)
  ? contactCandidateEmail
  : (
      !detectedAsForwarded && !mailboxOwnerSelfTask
        ? (productionCurrentContactLookupEmail || topLevelFrom)
        : productionCurrentContactLookupEmail
    );
const contactSelectionWinner = (detectedAsForwarded && forwardParserConfidence === 'high' && contactCandidateEmail)
  ? 'forward_parser'
  : (recommendedTaskContactLookupEmail ? 'production_logic' : 'none');
let contactAssociationDecision = 'no_association';
let contactAssociationReason = 'no_contact_candidate';
let manualReviewRequired = false;

if (mailboxOwnerSelfTask) {
  contactAssociationDecision = 'no_association';
  contactAssociationReason = 'mailbox_owner_self_task';
} else if (detectedAsForwarded && forwardParserConfidence === 'high' && contactCandidateEmail) {
  contactAssociationDecision = 'associate_existing_or_create';
  contactAssociationReason = forwardParserMatchedStrategy === 'gmail_forwarded_header'
    ? 'gmail_forward_header'
    : 'forwarded_body_from_high_confidence';
} else if (detectedAsForwarded && forwardParserConfidence !== 'high') {
  contactAssociationDecision = 'manual_review';
  contactAssociationReason = 'ambiguous_nested_forward';
  manualReviewRequired = true;
} else if (recommendedTaskContactLookupEmail) {
  contactAssociationDecision = 'associate_existing_or_create';
  contactAssociationReason = 'top_level_from_direct_message';
}

const shouldAssociateContact = Boolean(recommendedTaskContactLookupEmail) && !mailboxOwnerSelfTask;
const taskContactLookupEmail = recommendedTaskContactLookupEmail;
const contactNameParsed = parseContactName(taskContactLookupEmail);
const followUpContext = hasTaskAlias ? `alias-router:${gmailMessageId}:${aliasSignature}`.slice(0, 100) : '';

const validationErrors = [];
if (!gmailMessageId) validationErrors.push('missing_gmailMessageId');
if (!originatorEmail) validationErrors.push('missing_originatorEmail');
if (shouldAssociateContact && !taskContactLookupEmail) validationErrors.push('missing_taskContactLookupEmail');
if (!taskAliases.length) validationErrors.push('missing_task_alias_+task_or_+w');
if (allUnknownAliases.length) validationErrors.push('unknown_aliases_detected');

return [{
  json: {
    ...raw,
    timestamp,
    gmailMessageId,
    gmailThreadId,
    rfc822MessageId,
    gmailThreadUrl,
    gmailRfc822SearchUrl,
    gmailSubjectSearchUrl,
    subject,
    from: originatorEmail,
    originatorEmail,
    to: normalizedHeaders.to,
    cc: normalizedHeaders.cc,
    bcc: normalizedHeaders.bcc,
    deliveredTo: normalizedHeaders.deliveredTo,
    xForwardedTo: normalizedHeaders.xForwardedTo,
    validAliasWhitelist: VALID_ALIASES,
    allDetectedAliases,
    unknownAliases: allUnknownAliases,
    aliasSignature,
    canonicalAliasHeaderTrace,
    allHeaderAddressTrace,
    rawHeadersByName,
    detectedTaskClass,
    shouldCreateTask,
    route,
    taskTitle,
    humanNextAction,
    remainingBlocks,
    parsedDateFieldValue,
    productionCurrentContactLookupEmail,
    taskContactLookupEmail,
    contactNameParsed,
    externalRecipients,
    detectedAsForwarded,
    forwardParserConfidence,
    forwardParserMatchedStrategy,
    forwardParserContactCandidateEmail,
    recommendedTaskContactLookupEmail,
    contactSelectionWinner,
    winningSourceField,
    winningSourceValue,
    contactAssociationDecision,
    contactAssociationReason,
    manualReviewRequired,
    mailboxOwnerSelfTask,
    shouldAssociateContact,
    bodyText,
    followUpContext,
    validationErrors,
    diagnosticSummary: {
      payloadHasHeaders: Array.isArray(headers),
      payloadHeadersCount: headers.length,
      canonicalAliasHeadersScanned: CANONICAL_ALIAS_HEADERS,
      rawHeaderNames: headers.map((h) => h?.name).filter(Boolean),
      taskAliasFound: taskAliases.length > 0,
      classAliasesFound: classAliases,
      taskAliasesFound: taskAliases,
      detectedAsForwarded,
      forwardParserConfidence,
      forwardParserMatchedStrategy,
      forwardParserContactCandidateEmail,
      productionCurrentContactLookupEmail,
      recommendedTaskContactLookupEmail,
      contactSelectionWinner,
      winningSourceField,
      winningSourceValue,
      contactAssociationDecision,
      contactAssociationReason,
    },
  },
}];

const item = $json || {};

function hasValue(value) {
  if (Array.isArray(value)) return value.length > 0;
  return value !== undefined && value !== null && String(value).trim() !== '';
}

const detectedAliases = Array.isArray(item.allDetectedAliases) ? item.allDetectedAliases.map(String) : [];
const unknownAliases = Array.isArray(item.unknownAliases) ? item.unknownAliases.map(String) : [];
const taskAliases = detectedAliases.filter((a) => ['+task', '+w'].includes(a));
const hasTaskAlias = taskAliases.length > 0;
const followUpContext = String(item.followUpContext || "").trim();
const hasValidFollowUpContext = followUpContext.length > 0 && !followUpContext.endsWith(":none");

const diagnostics = {
  node: 'Code - Validate Normalized Payload RUN_19_SKIP_UNKNOWN',
  status: 'PASS',
  action: hasTaskAlias ? 'PROCESS_TASK' : 'SKIP_NON_TASK_ALIAS',
  skipWorkflow: !hasTaskAlias,
  skipReason: hasTaskAlias
    ? (hasValidFollowUpContext ? '' : 'Invalid followUpContext. Message is ignored by Task workflow.')
    : 'No task-producing alias detected. Message is ignored by Task workflow.',
  validAliasWhitelist: item.validAliasWhitelist || ['+task', '+w', '+rider', '+partner', '+h', '+supporter'],
  allDetectedAliases: item.allDetectedAliases || [],
  unknownAliases,
  aliasSignature: item.aliasSignature || '',
  gmailMessageId: item.gmailMessageId || '',
  gmailThreadId: item.gmailThreadId || '',
  subject: item.subject || '',
  from: item.from || '',
  originatorEmail: item.originatorEmail || '',
  taskContactLookupEmail: item.taskContactLookupEmail || '',
  followUpContext,
  bodyTextLength: String(item.bodyText || '').length,
  rawHeaderNames: item.diagnosticSummary?.rawHeaderNames || [],
  rawHeadersByName: item.rawHeadersByName || {},
  canonicalAliasHeaderTrace: item.canonicalAliasHeaderTrace || [],
  allHeaderAddressTrace: item.allHeaderAddressTrace || [],
};

if (!hasTaskAlias || !hasValidFollowUpContext) {
  return [{
    json: {
      ...item,
      normalizedValidation: diagnostics,
      shouldProcessTask: false,
      skipWorkflow: true,
      skipReason: diagnostics.skipReason,
      missingRequiredFields: [],
    },
  }];
}

const missingRequiredFields = [];
if (!hasValue(item.gmailMessageId)) missingRequiredFields.push('gmailMessageId');
if (!hasValue(item.originatorEmail)) missingRequiredFields.push('originatorEmail');
if (item.shouldAssociateContact && !hasValue(item.taskContactLookupEmail)) missingRequiredFields.push('taskContactLookupEmail');
if (!hasValue(item.followUpContext)) missingRequiredFields.push('followUpContext');

diagnostics.missingRequiredFields = missingRequiredFields;
diagnostics.status = missingRequiredFields.length ? 'FAIL' : 'PASS';

if (missingRequiredFields.length) {
  throw new Error('NORMALIZED_PAYLOAD_VALIDATION_FAILED ' + JSON.stringify(diagnostics));
}

return [{
  json: {
    ...item,
    normalizedValidation: diagnostics,
    shouldProcessTask: true,
    skipWorkflow: false,
    skipReason: '',
    missingRequiredFields,
  },
}];

