const n = $('Code - Normalize Email and Detect Aliases RUN_06').item.json || {};
const current = $json || {};

let contactId = '';
let contactRelationship = '';
let contactDisplayName = '';

const contactLookupBypassed = Boolean(current.contactLookupBypassed);
const allowContactAssociation = n.contactAssociationDecision === 'associate_existing_or_create';

if (allowContactAssociation && !contactLookupBypassed && Array.isArray(current.list) && current.list.length > 0) {
  const contact = current.list[0] || {};
  contactId = String(contact.id || '').trim();
  contactRelationship = String(contact.cRelationshipType || '').trim();
  contactDisplayName = String(contact.name || [contact.firstName, contact.lastName].filter(Boolean).join(' ').trim() || contact.emailAddress || '').trim();
} else if (allowContactAssociation && !contactLookupBypassed && current.id && (current.emailAddress || current.firstName || current.lastName || current.name)) {
  contactId = String(current.id || '').trim();
  contactRelationship = String(current.cRelationshipType || '').trim();
  contactDisplayName = String(current.name || [current.firstName, current.lastName].filter(Boolean).join(' ').trim() || current.emailAddress || current.contactName || '').trim();
}

const subject = String(n.subject || '').trim();
const subjectClean = subject.replace(/^((re|fwd|fw)\s*:\s*)+/i, '').replace(/\s+/g, ' ').trim();
const subjectSuffix = subjectClean ? subjectClean.slice(0, 40) : '';
const preferredTaskTitle = contactDisplayName
  ? `${contactDisplayName}${subjectSuffix ? ` | ${subjectSuffix}` : ''}`
  : (String(n.originatorEmail || '').trim() ? `${String(n.originatorEmail || '').trim()}${subjectSuffix ? ` | ${subjectSuffix}` : ''}` : subjectClean);

const taskTitle = (
  n.humanNextAction ||
  n.taskTitle ||
  preferredTaskTitle ||
  subjectClean ||
  'Task'
).slice(0, 140);
const validTaskClasses = ['Rider', 'Partner', 'Hospitality', 'Supporter'];
const effectiveTaskClass = validTaskClasses.includes(n.detectedTaskClass)
  ? n.detectedTaskClass
  : (validTaskClasses.includes(contactRelationship) ? contactRelationship : '');

return [{
  json: {
    ...n,
    contactId,
    contactRelationship,
    contactDisplayName,
    effectiveTaskClass,
    taskTitle,
    contactLookupBypassed,
    allowContactAssociation,
  },
}];

const n = $json || {};
return [{
  json: {
    ...n,
    contactId: '',
    contactRelationship: '',
    contactDisplayName: '',
    emailAddress: '',
    name: '',
    contactLookupBypassed: true,
  },
}];

