  // documented URLSearchParams-unavailable lesson, so link resolution cannot rely on it at all.
  const value = String(href || '').trim();
  if (!value) return null;
  if (/^https?:\/\//i.test(value)) return value;
  if (/^\/\//.test(value)) {
    const scheme = (baseUrl.match(/^https?:/i) || ['https:'])[0];
    return scheme + value;
