const LABELS = new Set(['canal-status-connector-output', 'canal-vnf-notices.normalized', 'canal-vnf-ignored-items', 'canal-source-health', 'canal-route-status-events.compat', 'canal-route-status-review-queue.compat', 'canal-route-status-source-health.compat']);
const results = [];
const items = $input.all();
for (let i = 0; i < items.length; i += 1) {
  const item = items[i];
  const fileName = (item.json && item.json.fileName) || 'unknown';
  const targetPath = fileName;
  const label = fileName.replace(/\.json$/, '');
  if (!item.binary || !item.binary.data) {
    results.push({ json: { label, targetPath, validJson: false, bytes: 0, error: 'No binary data read back for ' + fileName } });
    continue;
  }
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const text = buf.toString('utf8');
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (err) {
    results.push({ json: { label, targetPath, validJson: false, bytes: Buffer.byteLength(text, 'utf8'), error: 'Invalid JSON: ' + err.message } });
    continue;
  }
  let shapeError = null;
  if (label === 'canal-status-connector-output' && (!parsed.connectorId || !Array.isArray(parsed.sourceHealth) || !parsed.validation)) {
    shapeError = 'canal-status-connector-output missing connectorId, sourceHealth[], or validation';
  }
  if (label === 'canal-source-health' && !Array.isArray(parsed.sources)) {
    shapeError = 'canal-source-health missing sources[]';
  }
  if (!LABELS.has(label)) shapeError = shapeError || ('Unexpected output label: ' + label);
  results.push({ json: { label, targetPath, validJson: !shapeError, bytes: Buffer.byteLength(text, 'utf8'), error: shapeError } });
}
return results;

