const output = $input.first().json;
const errors = [];

// Hardening: if Fetch Dashboard Data caught a hard failure (e.g. an upstream 5xx that
// exhausted retries, or any other unexpected exception) it now returns a marker object
// instead of throwing, so this validation gate -- not a bare n8n execution error -- is
// what decides the outcome, and Final Status Validation Failed still produces a proper
// structured record instead of a silent/unreported crash.
if (output && output.fetchFailed) {
  errors.push(`Fetch Dashboard Data failed: ${output.fetchError}`);
}

if (!output || typeof output !== 'object') errors.push('output is not an object');
if (!Array.isArray(output.points)) errors.push('points is not an array');
if (Array.isArray(output.points) && output.points.length !== 10) errors.push(`expected 10 points, got ${output.points.length}`);

const expectedRideDays = ['RD00','RD01','RD02','RD03','RD04','RD05','RD06','RD07','RD08','RD09'];
const foundRideDays = Array.isArray(output.points) ? output.points.map(p => p.ride_day) : [];
for (const rd of expectedRideDays) {
  if (!foundRideDays.includes(rd)) errors.push(`missing ride day ${rd}`);
}

const VALID_TIERS = ['Good', 'Moderate', 'Degraded', 'Poor', 'Very Poor', 'Extremely Poor', 'Alert'];

if (Array.isArray(output.points)) {
  for (const p of output.points) {
    if (typeof p.todayHighF !== 'number' || p.todayHighF < -40 || p.todayHighF > 130) {
      errors.push(`${p.ride_day} todayHighF implausible or missing: ${p.todayHighF}`);
    }
    if (typeof p.todayLowF !== 'number' || p.todayLowF < -40 || p.todayLowF > 130) {
      errors.push(`${p.ride_day} todayLowF implausible or missing: ${p.todayLowF}`);
    }
    if (p.todayHighF !== undefined && p.todayLowF !== undefined && typeof p.todayHighF === 'number' && typeof p.todayLowF === 'number' && p.todayHighF < p.todayLowF) {
      errors.push(`${p.ride_day} todayHighF < todayLowF`);
    }
    if (!p.air_quality || (p.air_quality.tier === undefined)) {
      errors.push(`${p.ride_day} missing air_quality.tier field`);
    } else if (p.air_quality.tier !== null && !VALID_TIERS.includes(p.air_quality.tier)) {
      errors.push(`${p.ride_day} air_quality.tier has unexpected value: ${p.air_quality.tier}`);
    }
    if (!Array.isArray(p.historicalDates) || p.historicalDates.length !== 4) {
      errors.push(`${p.ride_day} historicalDates missing or wrong length`);
    } else {
      for (const h of p.historicalDates) {
        if (h.tier !== null && h.tier !== undefined && !VALID_TIERS.includes(h.tier)) {
          errors.push(`${p.ride_day} historicalDates[${h.date}] tier has unexpected value: ${h.tier}`);
        }
      }
    }
  }
}

if (!output.historical_dates || output.historical_dates.length !== 4) errors.push('historical_dates missing or wrong length');
if (!output.generatedAt) errors.push('generatedAt missing');
if (!output.route) errors.push('route missing');

const valid = errors.length === 0;
return [{ json: { valid, errors, output } }];

