// Runs once per property after the property-specific NewsAPI request.
const property = $('Load Properties').item.json;
const articles = Array.isArray($json.articles) ? $json.articles : [];
const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000);

const keywords = [property.name, property.city, ...(property.keywords || [])]
  .filter(Boolean)
  .map(k => k.toLowerCase());

const propertyArticles = articles
  .filter(a => a.publishedAt && new Date(a.publishedAt) > cutoff)
  .map(a => {
    const text = `${a.title || ''} ${a.description || ''}`.toLowerCase();
    const matches = keywords.filter(k => text.includes(k)).length;
    return {
      title: a.title || 'Untitled article',
      url: a.url || '',
      source: (a.source && a.source.name) || 'Unknown',
      publishedAt: a.publishedAt,
      relevance: keywords.length > 0 ? matches / keywords.length : 0
    };
  })
  .filter(a => a.relevance >= 0.6)
  .slice(0, 5);

return {
  json: {
    property_id: property.id,
    property_name: property.name,
    city: property.city,
    propertyArticles
  }
};

// Select at most one genuinely newsworthy town item.
// The alert text is capped at 140 characters. A link is included only for a serious event.
const propertyResult = $('Filter Property Results').item.json;
const articles = Array.isArray($json.articles) ? $json.articles : [];
const cutoffMs = Date.now() - 24 * 60 * 60 * 1000;

const normalize = value => String(value || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();

const cityNorm = normalize(propertyResult.city);
const propertyUrls = new Set(
  (propertyResult.propertyArticles || [])
    .map(a => a.url)
    .filter(Boolean)
);

const seriousTerms = [
  'incendie', 'wildfire', 'feu de foret', 'inondation', 'crue',
  'evacuation', 'explosion', 'attentat', 'attaque', 'fusillade',
  'shooting', 'seisme', 'earthquake', 'tempete', 'storm',
  'alerte rouge', 'red alert', 'urgence', 'emergency', 'fatal',
  'mort', 'deces', 'effondrement', 'collapse', 'contamination'
];

const highImpactTerms = [
  'greve', 'strike', 'fermeture', 'closure', 'route barree',
  'road closed', 'train annule', 'rail disruption', 'manifestation',
  'protest', 'accident', 'canicule', 'heatwave', 'alerte orange',
  'orange alert', 'transport', 'trafic', 'travaux', 'roadworks',
  'coupure de courant', 'power outage', 'blackout'
];

const civicTerms = [
  'mairie', 'municipal', 'prefecture', 'festival', 'evenement',
  'marche', 'hopital', 'tourisme', 'securite'
];

const noiseTerms = [
  'football', 'rugby', 'match', 'classement', 'transfert',
  'mercato', 'score', 'championnat'
];

const containsAny = (text, terms) => terms.filter(term => text.includes(term));

const candidates = articles
  .filter(a => a && a.publishedAt && new Date(a.publishedAt).getTime() >= cutoffMs)
  .filter(a => a.url && !propertyUrls.has(a.url))
  .map(a => {
    const title = String(a.title || '');
    const description = String(a.description || '');
    const titleNorm = normalize(title);
    const textNorm = normalize(`${title} ${description}`);

    if (!textNorm.includes(cityNorm)) return null;

    const seriousHits = containsAny(textNorm, seriousTerms);
    const highImpactHits = containsAny(textNorm, highImpactTerms);
    const civicHits = containsAny(textNorm, civicTerms);
    const noiseHits = containsAny(textNorm, noiseTerms);

    const ageHours = (Date.now() - new Date(a.publishedAt).getTime()) / 3600000;
    let score = titleNorm.includes(cityNorm) ? 4 : 2;
    score += seriousHits.length * 7;
    score += highImpactHits.length * 3;
    score += civicHits.length * 1.5;
    score += ageHours <= 12 ? 2 : 1;
    score -= noiseHits.length * 4;

    const isSerious =
      seriousHits.length > 0 ||
      textNorm.includes('fermeture totale') ||
      textNorm.includes('route barree') ||
      textNorm.includes('greve generale');

    return {
      title: title || description,
      url: a.url,
      source: (a.source && a.source.name) || 'Unknown',
      publishedAt: a.publishedAt,
      score,
      isSerious
    };
  })
  .filter(Boolean)
  .filter(a => a.title && a.score >= 6)
  .sort((a, b) =>
    b.score - a.score ||
    new Date(b.publishedAt) - new Date(a.publishedAt)
  );

const truncate = (text, maxLength = 140) => {
  const clean = String(text || '').replace(/\s+/g, ' ').trim();
  if (clean.length <= maxLength) return clean;
  const shortened = clean.slice(0, maxLength - 1);
  const lastSpace = shortened.lastIndexOf(' ');
  return `${shortened.slice(0, lastSpace > 90 ? lastSpace : maxLength - 1).trim()}…`;
};

const selected = candidates[0] || null;
const townNews = selected
  ? {
      summary: truncate(selected.title, 140),
      source: selected.source,
      publishedAt: selected.publishedAt,
      serious: selected.isSerious,
      url: selected.isSerious ? selected.url : null
    }
  : null;

return {
  json: {
