    'john+rider@biketourfrance.net': { relationship: 'Rider', aliasType: 'class' },
    'john+partner@biketourfrance.net': { relationship: 'Partner', aliasType: 'class' },
    'john+h@biketourfrance.net': { relationship: 'Hospitality', aliasType: 'class' },
    'john+supporter@biketourfrance.net': { relationship: 'Supporter', aliasType: 'class' }
  },
  mailboxOwnerEmail: 'john@biketourfrance.net',
  internalDomains: ['biketourfrance.net'],
  allowedRelationshipTypes: ['Rider', 'Partner', 'Hospitality', 'Supporter'],
  write_allowed: false,
  read_allowed: true,
