        attribute: 'emailAddress',
        value: candidateEmail,
        queryWasSkippedBySentinel: !candidateEmail,
        found,
        count: total,
        existingContact: existingContactSummary,
        rawResponseShape: {
          hasList: Array.isArray(lookup.list),
          hasRecords: Array.isArray(lookup.records),
          hasData: Array.isArray(lookup.data),
          topLevelKeys: Object.keys(lookup || {})
        }
      },
      duplicateSearchResult: {
