});

function asString(value) {
  return value === undefined || value === null ? '' : String(value);
}

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (value && typeof value === 'object') return Object.values(value);
  return [];
}

function unique(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function extractFieldDef(metadata) {
  if (!metadata || typeof metadata !== 'object') return null;

  if (metadata.type || metadata.options || metadata.isCustom || metadata.custom || metadata.view) {
    return metadata;
  }

  if (metadata.entityDefs?.Contact?.fields?.cRelationshipType) {
    return metadata.entityDefs.Contact.fields.cRelationshipType;
  }

  if (metadata.fields?.cRelationshipType) {
    return metadata.fields.cRelationshipType;
  }

  if (metadata.cRelationshipType) {
    return metadata.cRelationshipType;
  }

  return null;
}

function normalizeOptions(options) {
  if (Array.isArray(options)) return options.map(asString).filter(Boolean);
  if (options && typeof options === 'object') return Object.keys(options).map(asString).filter(Boolean);
  return [];
}

function makeWritePlan(item, schemaGate) {
  const blockers = [];
  const warnings = [];
  const candidate = item.candidate || {};
  const relationship = item.relationshipCandidate || {};
  const duplicate = item.duplicateSearchResult || {};
  const existing = item.espoDuplicateLookup?.existingContact || null;
  const existingRelationship = asString(duplicate.existingContactRelationshipType || existing?.cRelationshipType || '').trim();
  const targetRelationship = asString(relationship.value).trim();

  if (!schemaGate.pass) blockers.push('schema_gate_not_passed');
  if (item.write_allowed !== false) warnings.push('unexpected_write_allowed_not_false_in_v08');
  if (item.config?.espoWriteEnabled !== false) warnings.push('unexpected_espoWriteEnabled_not_false_in_v08');
  if (item.decision !== 'dry_run_preview') blockers.push(`parser_decision_${item.decision}`);
  if (!candidate.emailAddress) blockers.push('missing_candidate_email');
  if (!candidate.lastName) blockers.push('missing_required_lastName');
  if (!targetRelationship) blockers.push('missing_target_relationship');
  if (targetRelationship && !relationship.isAllowed) blockers.push('target_relationship_not_allowed');
  if (relationship.relationshipConflict) blockers.push('relationship_alias_directive_conflict');
  if (Number(item.espoDuplicateLookup?.count || 0) > 1) blockers.push('multiple_existing_contacts_for_email');
  if (Array.isArray(item.manualReviewReasons) && item.manualReviewReasons.length > 0) {
    blockers.push('manual_review_reason_present');
  }

  let action = 'manual_review';
  let reason = 'one_or_more_blockers';

  if (blockers.length === 0) {
    if (duplicate.existingContactFound) {
      if (existingRelationship === targetRelationship) {
        action = 'no_op_existing_contact_classification_matches';
        reason = 'existing_contact_already_has_target_relationship';
      } else {
        action = 'update_existing_contact_relationship_when_writes_enabled';
        reason = existingRelationship
          ? 'existing_contact_relationship_differs_from_alias'
          : 'existing_contact_relationship_blank';
      }
    } else {
      action = 'create_contact_when_writes_enabled';
      reason = 'no_existing_contact_found_and_candidate_is_valid';
    }
  } else if (!schemaGate.pass) {
    action = 'schema_gate_failed_no_write';
    reason = 'Contact.cRelationshipType schema gate did not pass';
  }

  const proposedCreatePayload = action === 'create_contact_when_writes_enabled' ? {
    firstName: candidate.firstName || '',
    lastName: candidate.lastName || '',
    emailAddress: candidate.emailAddress || '',
    cRelationshipType: targetRelationship,
    description: item.proposedContactPayload?.description || ''
  } : null;

  const proposedUpdatePayload = action === 'update_existing_contact_relationship_when_writes_enabled' ? {
    id: duplicate.existingContactId || existing?.id || '',
    cRelationshipType: targetRelationship
  } : null;

  return {
    action,
    reason,
    writeWillExecuteInV08: false,
    writeStatus: 'NO_WRITE_DRY_RUN_ONLY',
    targetField: 'Contact.cRelationshipType',
    targetRelationship,
    existingRelationship,
    relationshipChangedFrom: existingRelationship,
    relationshipChangedTo: action === 'update_existing_contact_relationship_when_writes_enabled' ? targetRelationship : '',
    existingContactId: duplicate.existingContactId || existing?.id || '',
    candidateEmailAddress: candidate.emailAddress || '',
    blockers: unique(blockers),
    warnings: unique(warnings),
    proposedCreatePayload,
    proposedUpdatePayload
  };
}

const metadataItems = $input.all();
