  const metadata = metadataItem.json || {};
  const fieldDef = extractFieldDef(metadata);
  const fieldExists = Boolean(fieldDef);
  const options = normalizeOptions(fieldDef?.options);
  const missingOptions = canonicalValues.filter((value) => !options.includes(value));
  const extraOptions = options.filter((value) => !canonicalValues.includes(value));
  const type = asString(fieldDef?.type);
  const writable = fieldExists && fieldDef?.readOnly !== true && fieldDef?.readOnlyAfterCreate !== true && fieldDef?.disabled !== true;
  const optionsKnown = options.length > 0;
  const supportsCanonicalValues = optionsKnown && missingOptions.length === 0;

  const schemaGate = {
    executed: true,
    readOnly: true,
    entity: 'Contact',
    field: 'cRelationshipType',
    fullFieldName: 'Contact.cRelationshipType',
    fieldExists,
    fieldType: type,
    writable,
    options,
    optionsKnown,
    canonicalValues,
    missingOptions,
    extraOptions,
    supportsCanonicalValues,
    pass: Boolean(fieldExists && writable && supportsCanonicalValues),
    rawResponseShape: {
      topLevelKeys: Object.keys(metadata || {}),
      fieldKeys: fieldDef && typeof fieldDef === 'object' ? Object.keys(fieldDef) : []
    }
  };

  const writePlan = makeWritePlan(original, schemaGate);

  return {
    json: {
      ...original,
      schemaGate,
