  test_directory: values.TEST_DIR || null,
  m4b_file: values.M4B_FILE || null,
  yt_dlp: {found: values.YT_DLP_FOUND === "true", path: values.YT_DLP_PATH || null, version: values.YT_DLP_VERSION || null},
  ffmpeg: {found: values.FFMPEG_FOUND === "true", path: values.FFMPEG_PATH || null, version: values.FFMPEG_VERSION || null},
  ffprobe: {found: values.FFPROBE_FOUND === "true", path: values.FFPROBE_PATH || null, version: values.FFPROBE_VERSION || null},
  m4b_created: values.M4B_CREATED === "true",
  m4b_size_bytes: Number(values.M4B_SIZE_BYTES || 0),
  m4b_duration_seconds: Number(values.M4B_DURATION_SECONDS || 0),
  mac_required: false,
  tested_at_utc: new Date().toISOString()
};
const failures=[];
if(!result.yt_dlp.found) failures.push("yt-dlp is unavailable");
if(!result.ffmpeg.found) failures.push("ffmpeg is unavailable");
if(!result.ffprobe.found) failures.push("ffprobe is unavailable");
