});

function normalizeItem(inputJson) {
  const input = inputJson || {};
  // Some upstream/manual-output paths can wrap the real item under a nested `json`.
  // Flatten it here so the write gate reads schemaGate/writePlan/config correctly.
  if (input.json && typeof input.json === 'object' && (input.json.workflowName || input.json.schemaGate || input.json.writePlan)) {
    return input.json;
  }
  return input;
}

function processOne(inputJson) {
  const item = normalizeItem(inputJson);
  const action = item.writePlan?.action || '';
  const schemaPass = item.schemaGate?.pass === true;
  const safetyFailures = Array.isArray(item.workflowSafetyFailures) ? item.workflowSafetyFailures : [];
  const writePlanBlockers = Array.isArray(item.writePlan?.blockers) ? item.writePlan.blockers : [];

  const globalWriteLock = {
    writeAllowed: item.write_allowed === true || item.config?.write_allowed === true,
    espoWriteEnabled: item.config?.espoWriteEnabled === true,
    oneContactWriteLimit: item.config?.max_contacts_to_create === 1,
    manualOnly: true,
    workflowName: 'v09b.H.Contact_Intake.DEV.WRITE_READY.NO_WRITE_DEFAULT.GATE_FIX'
  };

  const executeWrites = Boolean(
    globalWriteLock.writeAllowed &&
    globalWriteLock.espoWriteEnabled &&
    globalWriteLock.oneContactWriteLimit &&
    schemaPass &&
    safetyFailures.length === 0 &&
    writePlanBlockers.length === 0 &&
    [
      'create_contact_when_writes_enabled',
      'update_existing_contact_relationship_when_writes_enabled'
    ].includes(action)
  );

  const writeExecutionGate = {
    evaluated: true,
    executeWrites,
    writeStatus: executeWrites ? 'WRITE_ALLOWED_BY_GATE' : 'NO_WRITE_DEFAULT_LOCKED',
    globalWriteLock,
    schemaPass,
    action,
    safetyFailures,
    writePlanBlockers,
    reason: executeWrites
      ? 'All write gates passed.'
      : 'v09b is write-capable but globally locked by default; no write will execute unless write_allowed and espoWriteEnabled are explicitly true and writePlan has no blockers.'
  };

  return {
    json: {
      ...item,
      writeExecutionGate,
      writeStatus: writeExecutionGate.writeStatus,
      finalStatus: executeWrites
        ? 'WRITE_GATE_OPEN_REVIEW_BEFORE_EXECUTION'
        : 'WRITE_READY_NO_WRITE_DEFAULT_LOCKED'
    }
  };
}

return $input.all().map((item) => processOne(item.json || {}));

const VALID_ALIASES = ['+task', '+w', '+rider', '+partner', '+h', '+supporter'];
const TASK_ALIASES = ['+task', '+w'];
const CLASS_ALIAS_MAP = {
  '+rider': 'Rider',
  '+partner': 'Partner',
  '+h': 'Hospitality',
  '+supporter': 'Supporter',
};
const CANONICAL_ALIAS_HEADERS = ['Delivered-To', 'X-Forwarded-To', 'To', 'Cc', 'Bcc', 'X-Original-To', 'Envelope-To'];

function headerValues(headers, name) {
  if (!Array.isArray(headers)) return [];
  const target = String(name || '').toLowerCase();
  return headers
    .filter((item) => String(item?.name || '').toLowerCase() === target)
    .map((item) => String(item?.value || '').trim())
    .filter(Boolean);
}

function headerMap(headers) {
  const map = {};
  if (!Array.isArray(headers)) return map;
  for (const h of headers) {
    const name = String(h?.name || '').trim();
    const value = String(h?.value || '').trim();
    if (!name) continue;
    if (!map[name]) map[name] = [];
    if (value) map[name].push(value);
  }
  return map;
}

function walkParts(part) {
  if (!part || typeof part !== 'object') return [];
  const queue = [part];
  const out = [];
  while (queue.length) {
    const current = queue.shift();
    out.push(current);
    if (Array.isArray(current.parts)) queue.unshift(...current.parts);
  }
  return out;
}

function decodeBase64Url(data) {
  try {
    let b64 = String(data || '').replace(/-/g, '+').replace(/_/g, '/');
    while (b64.length % 4) b64 += '=';
    return Buffer.from(b64, 'base64').toString('utf8');
  } catch (error) {
    return '';
  }
}

function extractBodyText(payload) {
  const parts = walkParts(payload);
  for (const part of parts) {
    if (part?.mimeType === 'text/plain' && part?.body?.data) return decodeBase64Url(part.body.data);
  }
  for (const part of parts) {
    if (part?.body?.data) return decodeBase64Url(part.body.data);
  }
  if (payload?.body?.data) return decodeBase64Url(payload.body.data);
  return '';
}

function parseAddresses(rawValue) {
  if (!rawValue) return [];
  const matches = String(rawValue).match(/[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}/gi);
  return (matches || []).map((e) => e.trim().toLowerCase());
}

function uniqueValues(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function isInternalBtfAddress(address) {
  const domain = String(address || '').toLowerCase().split('@')[1] || '';
  return domain === 'biketourfrance.net';
}

function extractAliasesFromAddress(address) {
  const local = String(address || '').toLowerCase().split('@')[0] || '';
  const matches = local.match(/\+[a-z0-9]+/g) || [];
  return uniqueValues(matches);
}

function parseDirectiveBlocks(bodyText) {
  const blocks = [];
  for (const match of String(bodyText || '').matchAll(/\[\[([\s\S]*?)\]\]/g)) {
    const block = String(match[1] || '').trim();
    if (block) blocks.push(block);
  }
  return blocks;
}

function stripSubjectPrefixes(value) {
  return String(value || '').replace(/^((re|fwd|fw)\s*:\s*)+/i, '').replace(/\s+/g, ' ').trim();
}

function capitalize(value) {
  const text = String(value || '').trim();
  if (!text) return '';
  return text.charAt(0).toUpperCase() + text.slice(1).toLowerCase();
}

function parseContactName(email) {
  const local = String(email || '').split('@')[0] || '';
  const parts = local.replace(/[._+\-]+/g, ' ').split(/\s+/).filter(Boolean);
  if (parts.length === 0) return { firstName: '', lastName: '' };
  if (parts.length === 1) return { firstName: capitalize(parts[0]), lastName: '' };
  return { firstName: capitalize(parts[0]), lastName: parts.slice(1).map(capitalize).join(' ') };
}

function firstEmail(value) {
  return parseAddresses(value)[0] || String(value || '').trim().toLowerCase();
}

const raw = $json || {};
const payload = raw.payload || raw.data?.payload || raw.body?.payload || {};
const headers = Array.isArray(payload.headers)
  ? payload.headers
  : Array.isArray(raw.headers)
    ? raw.headers
    : [];

const rawHeadersByName = headerMap(headers);
const gmailMessageId = String(raw.id || raw.gmailMessageId || raw.data?.id || raw.body?.id || '').trim();
const gmailThreadId = String(raw.threadId || raw.gmailThreadId || raw.data?.threadId || raw.body?.threadId || '').trim();
const internalDate = String(raw.internalDate || raw.data?.internalDate || raw.body?.internalDate || '').trim();
const timestamp = internalDate ? new Date(Number(internalDate)).toISOString() : null;

const rawHeaderValues = {
  to: headerValues(headers, 'To'),
  deliveredTo: headerValues(headers, 'Delivered-To'),
  xForwardedTo: headerValues(headers, 'X-Forwarded-To'),
  cc: headerValues(headers, 'Cc'),
  bcc: headerValues(headers, 'Bcc'),
  subject: headerValues(headers, 'Subject'),
  from: headerValues(headers, 'From'),
  messageId: headerValues(headers, 'Message-ID'),
};

const normalizedHeaders = {
  to: uniqueValues(rawHeaderValues.to.flatMap(parseAddresses)),
  deliveredTo: uniqueValues(rawHeaderValues.deliveredTo.flatMap(parseAddresses)),
  xForwardedTo: uniqueValues(rawHeaderValues.xForwardedTo.flatMap(parseAddresses)),
  cc: uniqueValues(rawHeaderValues.cc.flatMap(parseAddresses)),
  bcc: uniqueValues(rawHeaderValues.bcc.flatMap(parseAddresses)),
};

const canonicalAliasHeaderTrace = [];
const allHeaderAddressTrace = [];
const detectedAliases = new Set();
const unknownAliases = new Set();

for (const headerName of CANONICAL_ALIAS_HEADERS) {
  const values = headerValues(headers, headerName);
  for (const rawValue of values) {
    const addresses = parseAddresses(rawValue);
    const trace = { headerName, rawValue, addresses, aliases: [] };
    for (const address of addresses) {
      const aliases = extractAliasesFromAddress(address);
      trace.aliases.push(...aliases);
      for (const alias of aliases) {
        if (VALID_ALIASES.includes(alias)) detectedAliases.add(alias);
        else unknownAliases.add(alias);
      }
    }
    canonicalAliasHeaderTrace.push(trace);
  }
}

for (const h of headers) {
  const headerName = String(h?.name || '').trim();
  const rawValue = String(h?.value || '').trim();
  const addresses = parseAddresses(rawValue);
  if (!addresses.length) continue;
  const aliases = uniqueValues(addresses.flatMap(extractAliasesFromAddress));
  for (const alias of aliases) {
    if (VALID_ALIASES.includes(alias)) detectedAliases.add(alias);
    else unknownAliases.add(alias);
  }
  allHeaderAddressTrace.push({ headerName, rawValue, addresses, aliases });
}

const allDetectedAliases = Array.from(detectedAliases);
const allUnknownAliases = Array.from(unknownAliases);
const taskAliases = allDetectedAliases.filter((a) => TASK_ALIASES.includes(a));
const classAliases = allDetectedAliases.filter((a) => Object.prototype.hasOwnProperty.call(CLASS_ALIAS_MAP, a));
const detectedTaskClass = classAliases.length > 0 ? CLASS_ALIAS_MAP[classAliases[0]] : null;
const hasTaskAlias = taskAliases.length > 0;
const shouldCreateTask = hasTaskAlias;
const aliasSignature = allDetectedAliases.length ? allDetectedAliases.join('') : 'none';
const route = hasTaskAlias ? 'route_task' : 'route_no_task_alias';

const bodyText = extractBodyText(payload);
const directiveBlocks = parseDirectiveBlocks(bodyText);
let parsedDateFieldValue = null;
const contentBlocks = [];
for (let i = 0; i < directiveBlocks.length; i++) {
  const block = directiveBlocks[i];
  const dateMatch = block.match(/^(due date|work date)\s+([0-3]\d-[A-Z]{3}-\d{4})$/i);
  if (i === 0) {
    contentBlocks.push(block);
  } else if (!parsedDateFieldValue && dateMatch) {
    const monthMap = { JAN:'01', FEB:'02', MAR:'03', APR:'04', MAY:'05', JUN:'06', JUL:'07', AUG:'08', SEP:'09', OCT:'10', NOV:'11', DEC:'12' };
    const bits = String(dateMatch[2] || '').toUpperCase().match(/^([0-3]\d)-([A-Z]{3})-(\d{4})$/);
    if (bits && monthMap[bits[2]]) parsedDateFieldValue = `${bits[3]}-${monthMap[bits[2]]}-${bits[1]}`;
  } else {
    contentBlocks.push(block);
  }
}

const subject = String(rawHeaderValues.subject[0] || raw.subject || '').trim();
const subjectClean = stripSubjectPrefixes(subject);
const humanNextAction = contentBlocks[0] || null;
const remainingBlocks = contentBlocks.slice(1);
const taskTitle = (humanNextAction || subjectClean || 'Task').slice(0, 140);

const externalRecipients = uniqueValues([
  ...normalizedHeaders.to,
  ...normalizedHeaders.cc,
  ...normalizedHeaders.bcc,
].filter((addr) => !isInternalBtfAddress(addr)));
const productionCurrentContactLookupEmail = externalRecipients[0] || '';
const mailboxOwnerEmail = String('john@biketourfrance.net').trim().toLowerCase();
const fromHeader = rawHeaderValues.from[0] || raw.from || '';
const originatorEmail = firstEmail(fromHeader);
const topLevelFrom = originatorEmail;
const bodyTextForwarded = /forwarded message|begin forwarded message|original message|forwarded by/i.test(bodyText);
const subjectLooksForwarded = /^(fwd|fw):/i.test(subject) || /\bforwarded\b/i.test(subject);
const explicitOriginalSender = firstAddressFromMany(
  rawHeaderValues['x-original-from']?.[0],
  rawHeaderValues['x-original-sender']?.[0],
  rawHeaderValues['x-google-original-from']?.[0],
  rawHeaderValues['x-forwarded-from']?.[0],
  rawHeaderValues['resent-from']?.[0],
  rawHeaderValues['resent-sender']?.[0]
);

function firstAddressFromMany(...values) {
  for (const value of values) {
    const email = firstEmail(value);
    if (email) return email;
  }
  return '';
}

function dedupePreserveOrder(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function headerLineValue(lines, key) {
  const prefix = String(key || '').toLowerCase() + ':';
  for (const line of lines) {
    const trimmed = String(line || '').trim();
    if (trimmed.toLowerCase().startsWith(prefix)) {
      return trimmed.slice(prefix.length).trim();
    }
  }
  return '';
}

function parseForwardBlocks(text) {
  const lines = String(text || '').split(/\r?\n/);
  const markerRegex = /forwarded message|begin forwarded message|original message|forwarded by/i;
  const markerIndexes = [];
  for (let i = 0; i < lines.length; i += 1) {
    if (markerRegex.test(lines[i])) markerIndexes.push(i);
  }

  const blocks = [];
  for (let i = 0; i < markerIndexes.length; i += 1) {
    const start = markerIndexes[i] + 1;
    const end = i + 1 < markerIndexes.length ? markerIndexes[i + 1] : lines.length;
    const slice = lines.slice(start, end);
    const headerLines = [];
    for (const line of slice) {
      if (!String(line || '').trim()) {
        if (headerLines.length > 0) break;
        continue;
      }
      headerLines.push(line);
      if (headerLines.length >= 24) break;
    }
    blocks.push({
      markerLine: String(lines[markerIndexes[i]] || '').trim(),
      fromEmail: firstAddressFromMany(headerLineValue(headerLines, 'From')),
      senderEmail: firstAddressFromMany(headerLineValue(headerLines, 'Sender')),
      replyToEmail: firstAddressFromMany(headerLineValue(headerLines, 'Reply-To')),
      subject: headerLineValue(headerLines, 'Subject'),
      date: headerLineValue(headerLines, 'Date'),
      toEmail: firstAddressFromMany(headerLineValue(headerLines, 'To')),
      rawHeaderLines: headerLines,
    });
  }

  return blocks;
}

const forwardedBlocks = parseForwardBlocks(bodyText);
const bodyForwardCandidate = [...forwardedBlocks].reverse().find((block) => block.fromEmail || block.senderEmail || block.replyToEmail) || null;
const detectedAsForwarded = Boolean(explicitOriginalSender || bodyForwardCandidate || subjectLooksForwarded || bodyTextForwarded);

let forwardParserContactCandidateEmail = '';
let forwardParserMatchedStrategy = 'unresolved';
let forwardParserConfidence = 'not_applicable';
let winningSourceField = '';
let winningSourceValue = '';
const notes = [];

if (explicitOriginalSender) {
  forwardParserContactCandidateEmail = explicitOriginalSender;
  winningSourceField = rawHeaderValues['x-original-from']?.[0]
    ? 'x-original-from'
    : (rawHeaderValues['x-original-sender']?.[0]
      ? 'x-original-sender'
      : (rawHeaderValues['x-google-original-from']?.[0]
        ? 'x-google-original-from'
        : (rawHeaderValues['x-forwarded-from']?.[0]
          ? 'x-forwarded-from'
          : (rawHeaderValues['resent-from']?.[0] ? 'resent-from' : 'resent-sender'))));
  winningSourceValue = forwardParserContactCandidateEmail;
  forwardParserMatchedStrategy = 'gmail_forwarded_header';
  forwardParserConfidence = 'high';
  notes.push('Explicit original-sender header found in Gmail metadata.');
} else if (bodyForwardCandidate?.fromEmail || bodyForwardCandidate?.senderEmail || bodyForwardCandidate?.replyToEmail) {
  forwardParserContactCandidateEmail = bodyForwardCandidate.fromEmail || bodyForwardCandidate.senderEmail || bodyForwardCandidate.replyToEmail || '';
  winningSourceField = bodyForwardCandidate.fromEmail ? 'forwarded_body_from' : (bodyForwardCandidate.senderEmail ? 'forwarded_body_sender' : 'forwarded_body_reply_to');
  winningSourceValue = forwardParserContactCandidateEmail;
  forwardParserMatchedStrategy = forwardedBlocks.length > 1 ? 'nested_forwarded_body_block' : 'forwarded_body_block';
  forwardParserConfidence = forwardedBlocks.length > 1 ? 'medium' : 'high';
  notes.push(`Forwarded body marker(s) found: ${forwardedBlocks.length}.`);
  if (forwardedBlocks.length > 1) {
    notes.push('Multiple forwarded layers reduce certainty about the true original sender.');
  }
} else if (!detectedAsForwarded && topLevelFrom) {
  forwardParserContactCandidateEmail = topLevelFrom;
  winningSourceField = 'top_level_from';
  winningSourceValue = topLevelFrom;
  forwardParserMatchedStrategy = 'gmail_top_level_from';
  forwardParserConfidence = 'not_applicable';
  notes.push('No forwarded markers observed; top-level From is used only as a direct-message fallback.');
} else if (detectedAsForwarded) {
  forwardParserMatchedStrategy = 'forwarded_ambiguous_no_sender';
  forwardParserConfidence = 'low';
  winningSourceField = 'unresolved';
  winningSourceValue = '';
