      forwardParserMatchedStrategy,
      forwardParserContactCandidateEmail,
      productionCurrentContactLookupEmail,
      recommendedTaskContactLookupEmail,
      contactSelectionWinner,
      winningSourceField,
      winningSourceValue,
      contactAssociationDecision,
      contactAssociationReason,
    },
  },
}];

const item = $json || {};

function hasValue(value) {
  if (Array.isArray(value)) return value.length > 0;
  return value !== undefined && value !== null && String(value).trim() !== '';
}

const detectedAliases = Array.isArray(item.allDetectedAliases) ? item.allDetectedAliases.map(String) : [];
const unknownAliases = Array.isArray(item.unknownAliases) ? item.unknownAliases.map(String) : [];
const taskAliases = detectedAliases.filter((a) => ['+task', '+w'].includes(a));
const hasTaskAlias = taskAliases.length > 0;
const followUpContext = String(item.followUpContext || "").trim();
const hasValidFollowUpContext = followUpContext.length > 0 && !followUpContext.endsWith(":none");

const diagnostics = {
  node: 'Code - Validate Normalized Payload RUN_19_SKIP_UNKNOWN',
  status: 'PASS',
  action: hasTaskAlias ? 'PROCESS_TASK' : 'SKIP_NON_TASK_ALIAS',
  skipWorkflow: !hasTaskAlias,
  skipReason: hasTaskAlias
    ? (hasValidFollowUpContext ? '' : 'Invalid followUpContext. Message is ignored by Task workflow.')
    : 'No task-producing alias detected. Message is ignored by Task workflow.',
  validAliasWhitelist: item.validAliasWhitelist || ['+task', '+w', '+rider', '+partner', '+h', '+supporter'],
  allDetectedAliases: item.allDetectedAliases || [],
  unknownAliases,
  aliasSignature: item.aliasSignature || '',
  gmailMessageId: item.gmailMessageId || '',
  gmailThreadId: item.gmailThreadId || '',
  subject: item.subject || '',
  from: item.from || '',
  originatorEmail: item.originatorEmail || '',
  taskContactLookupEmail: item.taskContactLookupEmail || '',
  followUpContext,
  bodyTextLength: String(item.bodyText || '').length,
  rawHeaderNames: item.diagnosticSummary?.rawHeaderNames || [],
  rawHeadersByName: item.rawHeadersByName || {},
  canonicalAliasHeaderTrace: item.canonicalAliasHeaderTrace || [],
  allHeaderAddressTrace: item.allHeaderAddressTrace || [],
};

if (!hasTaskAlias || !hasValidFollowUpContext) {
  return [{
    json: {
      ...item,
      normalizedValidation: diagnostics,
      shouldProcessTask: false,
      skipWorkflow: true,
      skipReason: diagnostics.skipReason,
      missingRequiredFields: [],
    },
  }];
}

const missingRequiredFields = [];
if (!hasValue(item.gmailMessageId)) missingRequiredFields.push('gmailMessageId');
if (!hasValue(item.originatorEmail)) missingRequiredFields.push('originatorEmail');
if (item.shouldAssociateContact && !hasValue(item.taskContactLookupEmail)) missingRequiredFields.push('taskContactLookupEmail');
if (!hasValue(item.followUpContext)) missingRequiredFields.push('followUpContext');

diagnostics.missingRequiredFields = missingRequiredFields;
diagnostics.status = missingRequiredFields.length ? 'FAIL' : 'PASS';

if (missingRequiredFields.length) {
  throw new Error('NORMALIZED_PAYLOAD_VALIDATION_FAILED ' + JSON.stringify(diagnostics));
}

return [{
  json: {
    ...item,
    normalizedValidation: diagnostics,
    shouldProcessTask: true,
    skipWorkflow: false,
    skipReason: '',
    missingRequiredFields,
  },
}];

