={{ (() => {
  const c = $('Code - Build Contact Context').item.json || {};
  const followUpContext = String(c.followUpContext || '').trim();

  if (!followUpContext || followUpContext.endsWith(':none')) {
    throw new Error(`REFUSING_TO_CREATE_TASK_FOR_INVALID_FOLLOWUP_CONTEXT: ${followUpContext || '<empty>'}`);
  }

  const validTaskClasses = ['Rider', 'Partner', 'Hospitality', 'Supporter'];
  const effectiveTaskClass = validTaskClasses.includes(c.effectiveTaskClass)
    ? c.effectiveTaskClass
    : (validTaskClasses.includes(c.detectedTaskClass) ? c.detectedTaskClass : '');

  const safeContactId = (c.contactAssociationDecision === 'associate_existing_or_create' && c.contactId)
    ? String(c.contactId).trim()
    : '';

  const baseTaskName = String(c.taskTitle || c.subject || 'Task').trim();
