parameters.jsCode:
const acknowledgedSequence = Number($('Acknowledge Webhook').first().json.query.sequence);
const now = new Date().toISOString();

const rows = items.map((item, index) => ({
  ...item.json,
  _rowNumber: index + 2,
  sequence: Number(item.json.sequence),
  cycle_count: Number(item.json.cycle_count || 0),
}));

const maxSequence = Math.max(...rows.map((row) => row.sequence));
const acknowledged = rows.find((row) => row.sequence === acknowledgedSequence);

if (!acknowledged) {
  throw new Error(`No tracker row found for sequence ${acknowledgedSequence}`);
}

const nextSequence = acknowledgedSequence >= maxSequence ? 1 : acknowledgedSequence + 1;
const completingCycle = nextSequence === 1;

return rows.map((row) => {
  let status = row.status;
  let acknowledged_at = row.acknowledged_at;
  let cycle_count = row.cycle_count;

  if (row.sequence === acknowledgedSequence) {
    status = 'done';
    acknowledged_at = now;
  }

  if (completingCycle) {
    status = 'pending';
    cycle_count += 1;
  }

  if (row.sequence === nextSequence) {
    status = 'current';
  }

  return {
    json: {
      sequence: row.sequence,
      tab_title: row.tab_title,
      tab_id: row.tab_id,
      tab_url: row.tab_url,
      status,
      last_sent_at: row.last_sent_at,
      acknowledged_at,
      cycle_count,
      notes: row.notes || ''
    }
  };
});

// Read config row (first row of Config sheet)
const config = $input.first().json;
const dateRangeDays = parseInt(config.date_range_days) || 60;
const origins = String(config.origins || 'SEA,PAE').split(',').map(x => x.trim()).filter(Boolean);
const destination = String(config.destination || 'PHX').trim();

const today = new Date();
const items = [];

for (let i = 0; i < dateRangeDays; i++) {
  const travelDate = new Date(today);
  travelDate.setDate(travelDate.getDate() + i);
  const dateStr = travelDate.toISOString().split('T')[0];

  for (const origin of origins) {
    items.push({
      json: {
        departure_id: origin,
        arrival_id: destination,
        outbound_date: dateStr
      }
    });
  }
}

return items;

// Extract the lowest fare from the SerpAPI Google Flights response.
// Query details come back in search_parameters, so no cross-node references needed.
const r = $input.first().json;
const sp = r.search_parameters || {};
const todayStr = new Date().toISOString().split('T')[0];

const flights = [...(r.best_flights || []), ...(r.other_flights || [])];

if (flights.length === 0) {
  return [{
    json: {
      date_checked: todayStr,
      travel_date: sp.outbound_date || 'unknown',
      origin: sp.departure_id || 'unknown',
      destination: sp.arrival_id || 'unknown',
      price: '',
      carrier: 'NO FLIGHTS FOUND',
      stops: '',
      timestamp: new Date().toISOString()
    }
  }];
}

let best = null;
for (const f of flights) {
  const price = typeof f.price === 'number' ? f.price : parseInt(String(f.price || '').replace(/[^0-9]/g, ''));
  if (!price || isNaN(price)) continue;
  if (!best || price < best.price) {
    best = {
      price: price,
      carrier: f.flights?.[0]?.airline || 'unknown',
      stops: Math.max((f.flights?.length || 1) - 1, 0)
    };
  }
}

return [{
  json: {
    date_checked: todayStr,
    travel_date: sp.outbound_date || 'unknown',
    origin: sp.departure_id || 'unknown',
    destination: sp.arrival_id || 'unknown',
    price: best ? best.price : '',
    carrier: best ? best.carrier : 'unknown',
    stops: best ? best.stops : '',
    timestamp: new Date().toISOString()
  }
}];

// Build the report from today's rows in the History sheet.
const config = $('Read Config from Sheets').first().json;
const floor = parseFloat(config.absolute_floor_usd) || 120;
const todayStr = new Date().toISOString().split('T')[0];

const rows = $input.all().map(i => i.json)
  .filter(r => String(r.date_checked) === todayStr && r.price !== '' && r.price !== null && r.price !== undefined);

const priced = rows.map(r => ({ ...r, price: Number(r.price) })).filter(r => !isNaN(r.price));

const belowFloor = priced.filter(r => r.price < floor);
const cheapest = [...priced].sort((a, b) => a.price - b.price).slice(0, 5);

let body = `Flight Price Report – ${todayStr}\n`;
body += `================================\n\n`;

if (priced.length === 0) {
  body += `No prices were collected today. Check the workflow execution log.\n`;
}

if (belowFloor.length > 0) {
  body += `DEALS (below $${floor}):\n`;
  for (const f of belowFloor) {
    body += `  ${f.origin} -> ${f.destination} on ${f.travel_date}: $${f.price} (${f.carrier}, ${f.stops} stops)\n`;
  }
  body += `\n`;
}

if (cheapest.length > 0) {
  body += `5 Cheapest Days to Fly:\n`;
  cheapest.forEach((f, i) => {
    body += `  ${i + 1}. ${f.origin} -> ${f.destination} ${f.travel_date}: $${f.price} (${f.carrier})\n`;
  });
}

body += `\n---\n`;
body += `Monitoring: ${config.origins} -> ${config.destination}\n`;
body += `Range: ${config.date_range_days} days | Deal floor: $${floor}\n`;

return [{ json: { emailBody: body, subjectDate: todayStr } }];

// Read config from the sheet
const config = items[0].json;
const dateRangeDays = parseInt(config.date_range_days) || 60;
const origins = (config.origins || 'SEA,PAE').split(',').map(x => x.trim());
const destination = config.destination || 'PHX';
const signalThreshold = parseFloat(config.signal_threshold_percent) || 15;
const absoluteFloor = parseFloat(config.absolute_floor_usd) || 120;

// Generate dates
const today = new Date();
const queries = [];

for (let i = 0; i < dateRangeDays; i++) {
  const travelDate = new Date(today);
  travelDate.setDate(travelDate.getDate() + i);
  const dateStr = travelDate.toISOString().split('T')[0];

  for (const origin of origins) {
    queries.push({
      date: dateStr,
      origin: origin,
      destination: destination,
      departure_id: origin,
      arrival_id: destination,
      outbound_date: dateStr
    });
  }
}

return [{
  json: {
    queries: queries,
    totalQueries: queries.length,
    dateRangeDays: dateRangeDays,
    origins: origins,
    destination: destination,
    signalThreshold: signalThreshold,
    absoluteFloor: absoluteFloor,
    executedAt: new Date().toISOString()
  }
}];

// Extract the lowest fare from SerpAPI result
const flightData = items[0].json;
const query = items[0].json.query_metadata || {};
const flights = flightData.best_flights || [];

if (!flights || flights.length === 0) {
  return [{
    json: {
      date: query.outbound_date || 'unknown',
      origin: query.departure_id || 'unknown',
      destination: query.arrival_id || 'unknown',
      price: null,
      carrier: null,
      stops: null,
      error: 'No flights found',
      timestamp: new Date().toISOString()
    }
  }];
}

const lowestFare = flights.reduce((min, flight) => {
  const price = parseInt(flight.price.replace(/[^0-9]/g, ''));
  return price < (min.price || Infinity) ? { price, flight } : min;
}, {});

return [{
  json: {
    date: query.outbound_date || 'unknown',
