function walkParts(part) { if (!part || typeof part !== 'object') return []; const q=[part], out=[]; while(q.length){ const cur=q.shift(); out.push(cur); if(Array.isArray(cur.parts)) q.unshift(...cur.parts); } return out; }
function decodeBase64Url(data) { try { let b64=asString(data).replace(/-/g,'+').replace(/_/g,'/'); while(b64.length%4) b64+='='; return Buffer.from(b64,'base64').toString('utf8'); } catch(e){ return ''; } }
function extractBodyText(payload, fallbackRaw) { if (asString(fallbackRaw.bodyText).trim()) return asString(fallbackRaw.bodyText); const parts=walkParts(payload); for (const part of parts) if (part?.mimeType==='text/plain' && part?.body?.data) return decodeBase64Url(part.body.data); for (const part of parts) if (part?.body?.data) return decodeBase64Url(part.body.data); if (payload?.body?.data) return decodeBase64Url(payload.body.data); return ''; }

function stripDelimitedSignatureBlocks(text) {
  const lines = asString(text).split(/\r?\n/);
