  const hasExplicitImpact = explicit || combined;
  const normalizedT = t.normalize('NFKD').replace(/[\u0300-\u036f]/g, '');
  return {
    routeImpactStatus: hasExplicitImpact ? 'reported' : 'not_indicated',
    routeClosureConfirmed: false,
    towpathClosureConfirmed: hasExplicitImpact && /chemin de halage|halage/i.test(t),
    publicAccessClosureConfirmed: hasExplicitImpact && /acc[èe]s public/i.test(t),
    detourConfirmed: hasExplicitImpact && /d[ée]viation/i.test(t),
    hasCyclistTermMention: /(chemin de halage|voie verte|piste cyclable|velo|cyclable|cycliste)/i.test(normalizedT),
