// Adapted from fetch-prefectures.mjs's buildLocationIndex()/locateArticle(), using the segment list
// embedded in "Load / Embed Department Route Context" (real repo data - never invented).
const contextItems = $items('Load / Embed Department Route Context');
const segments = (contextItems[0] && contextItems[0].json.segments) || [];
const items = $input.all().map((i) => i.json || {});

function normalize(value) {
  return String(value || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[’']/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
}
