    return pattern.test(normalized);
  });
  if (!match) {
    return { locationText: 'D\u00e9partement ' + sourceDepartment, department: sourceDepartment, confidence: 'low', routeRelation: 'same_department', rideDays: [], distanceFromRouteKm: null };
  }
  const segment = match.segment;
  const matchedDepartment = segment.departments.includes(sourceDepartment) ? sourceDepartment : segment.departments[0];
  return {
    locationText: match.name,
    commune: match.name,
    department: matchedDepartment,
    confidence: 'medium',
    routeRelation: 'near_route',
