return items.map((item) => {
  if (item.recordKind !== 'parsedGovernmentItem') return { json: item };
  const location = locate(item.title + ' ' + item.evidenceText, item.department);
  const mappingConfidence = location.confidence;
  return { json: { ...item, ...location, mappingConfidence } };
});

// Produces normalized official government alert records with a strict four-way
