  },
  contactIntakeAliases: {
    'john+task@biketourfrance.net': { action: 'check_contact', relationship: '', aliasType: 'workflow', followupType: 'task' },
    'john+w@biketourfrance.net': { action: 'check_contact', relationship: '', aliasType: 'workflow', followupType: 'waiting' },
    'john+rider@biketourfrance.net': { action: 'create_or_update_contact', relationship: 'Rider', aliasType: 'class' },
    'john+partner@biketourfrance.net': { action: 'create_or_update_contact', relationship: 'Partner', aliasType: 'class' },
    'john+h@biketourfrance.net': { action: 'create_or_update_contact', relationship: 'Hospitality', aliasType: 'class' },
    'john+supporter@biketourfrance.net': { action: 'create_or_update_contact', relationship: 'Supporter', aliasType: 'class' }
  }
};
const config = { ...defaultConfig, ...(input.config || {}) };
config.contactIntakeAliases = { ...defaultConfig.contactIntakeAliases, ...((input.config || {}).contactIntakeAliases || {}) };
const raw = input.rawGmail || input;

function asString(value) { return value === undefined || value === null ? '' : String(value); }
function normalizeEmail(value) { return asString(value).trim().toLowerCase(); }
