function stripDelimitedSignatureBlocks(text) {
  const lines = asString(text).split(/\r?\n/);
  const kept = [];
  const strippedBlocks = [];
  let inBlock = false;
  let current = [];

  for (const rawLine of lines) {
    const normalized = asString(rawLine).replace(/^>\s*/, '').trim();
    if (normalized === '====') {
      current.push(rawLine);
      if (!inBlock) {
        inBlock = true;
      } else {
        strippedBlocks.push(current.join('\n'));
        current = [];
        inBlock = false;
      }
      continue;
    }
    if (inBlock) current.push(rawLine);
    else kept.push(rawLine);
  }

  if (inBlock && current.length) {
    strippedBlocks.push(current.join('\n'));
  }

  return { text: kept.join('\n'), strippedBlocks, strippedDelimitedBlockCount: strippedBlocks.length };
}

function isBtfOperatorSignatureLine(line) {
  const l = asString(line).toLowerCase();
  return l.includes('john brooks') ||
