}

function findFirstForwardedMarkerIndex(lines) {
  for (let i = 0; i < lines.length; i++) {
    if (hasForwardedMessageMarker(lines[i])) return i;
  }
  return -1;
}

function stripDanglingGmailSeparator(text) {
  const lines = asString(text).split(/\r?\n/);
