  }

  let keptPrefix = candidateTailLines;
  if (cutIndex >= 0) {
    strippedBlocks.push(candidateTailLines.slice(cutIndex).join('\n'));
    keptPrefix = candidateTailLines.slice(0, cutIndex);
  }

  const cleanedPrefix = stripDanglingGmailSeparator(keptPrefix.join('\n'));
