function tierForCode(codeQual) {
  if (codeQual === null || codeQual === undefined) return null;
  return QUAL_LABEL_EN[codeQual] || null;
}

function qs(obj) {
  return Object.entries(obj)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join("&");
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function fetchJson(url, headers, attempt) {
  attempt = attempt || 1;
  try {
    return await ctx.helpers.httpRequest({
      method: "GET",
      url,
      headers: headers || {},
      json: true,
      timeout: 30000,
    });
  } catch (e) {
    const status =
      (e && e.response && (e.response.status || e.response.statusCode)) ||
      e.statusCode ||
      e.httpCode ||
      e.status ||
      undefined;
    const isTransient = status === undefined || status >= 500;
    if (isTransient && attempt < 5) {
      await sleep(Math.min(12000, 1500 * (2 ** (attempt - 1))));
      return fetchJson(url, headers, attempt + 1);
    }
    const err = new Error(e && e.message ? e.message : String(e));
    if (status !== undefined) err.status = Number(status);
    throw err;
  }
}

async function atmoQuery(zoneCode, dateEch) {
  const filt = { code_zone: { operator: "=", value: zoneCode }, date_ech: { operator: "=", value: dateEch } };
