  try {
    const data = await fetchJson(url, { Authorization: `Bearer ${token}` });
    const feats = data.features || [];
    if (!feats.length) return null;
    return feats[0].properties;
  } catch (e) {
    if (e.status !== undefined) return null;
    throw e;
  }
}

async function currentAirQuality(town) {
