}

const EAQI_TIER_MAP = [[20, "Good"], [40, "Moderate"], [60, "Degraded"], [80, "Poor"], [100, "Very Poor"]];
function eaqiTier(eaqi) {
  if (eaqi === null || eaqi === undefined) return null;
  for (const [threshold, tier] of EAQI_TIER_MAP) {
    if (eaqi < threshold) return tier;
