  const schemaPass = j.schemaGate?.pass === true;
  const safetyFailures = Array.isArray(j.workflowSafetyFailures) ? j.workflowSafetyFailures : [];
  const writePlanBlockers = Array.isArray(j.writePlan?.blockers) ? j.writePlan.blockers : [];
  const proposedPayload = j.writePlan?.proposedCreatePayload || {};
  const targetChecks = {
    gmailMessageIdMatches: gmailMessageId === APPROVED.gmailMessageId,
    candidateEmailMatches: candidate === APPROVED.candidateEmailAddress,
    targetRelationshipMatches: targetRelationship === APPROVED.targetRelationship,
    actionMatches: action === APPROVED.expectedAction,
    approvedActionIsCreateOnly: action === 'create_contact_when_writes_enabled',
    hasFirstName: Boolean(proposedPayload.firstName),
    hasLastName: Boolean(proposedPayload.lastName),
    hasEmailAddress: proposedPayload.emailAddress === APPROVED.candidateEmailAddress
  };
  const approvedTargetMatches = Object.values(targetChecks).every(Boolean);
  const executeWrites = Boolean(
    !used &&
    j.config?.write_allowed === true &&
    j.config?.espoWriteEnabled === true &&
    schemaPass &&
    safetyFailures.length === 0 &&
    writePlanBlockers.length === 0 &&
    approvedTargetMatches
  );
  if (executeWrites) used = true;
  const writeExecutionGate = {
    evaluated: true,
    executeWrites,
    writeStatus: executeWrites ? 'PROD_APPLY_V12C_ONE_APPROVED_ACCOUNT_CONTACT_CREATE_GATE_OPEN' : 'PROD_APPLY_V12C_WRITE_GATE_CLOSED',
    globalWriteLock: {
      writeAllowed: j.config?.write_allowed === true,
      espoWriteEnabled: j.config?.espoWriteEnabled === true,
      manualOnly: true,
      workflowName: 'PROD_APPLY.v12c.Contact_Intake.ONE_APPROVED_ACCOUNT_CONTACT_CREATE',
      productionTarget: true,
      oneApprovedWriteOnly: true,
      approvedTarget: APPROVED
    },
    schemaPass,
    action,
    safetyFailures,
    writePlanBlockers,
    targetChecks,
    approvedTargetMatches,
    reason: executeWrites
      ? 'Exactly one approved PROD Account+Contact create path is allowed for this manual run.'
      : 'No write: not the single approved Chartreuse create target, failed schema/safety, blocked write plan, or write already used.'
  };
  return { json: {
    ...j,
    writeExecutionGate,
    writeStatus: writeExecutionGate.writeStatus,
    finalStatus: executeWrites ? 'PROD_APPLY_V12C_ACCOUNT_CONTACT_CREATE_WILL_EXECUTE' : 'PROD_APPLY_V12C_WRITE_NOT_EXECUTED_FOR_THIS_ITEM'
  }};
});

