const buffer = Buffer.from(($json.stdout || '').trim(), 'base64');
const binaryData = await this.helpers.prepareBinaryData(buffer, summary.finalFilename, 'audio/mp4');
return [{ json: { ...summary, uploadedFromPath: summary.syntheticResult.output_path }, binary: { data: binaryData } }];
